/* رفيق الداعية — دفعة إضافية: 36 مقالة قصيرة (a40–a75) و40 سؤالًا للباحثين (f21–f60).
   الآيات والأحاديث بأرقامها فقط من المراجع الموثقة في docs/REFS.md؛ نصوصها تُجلب من QuranEnc وHadeethEnc كما هي.
   النصوص المؤلَّفة تحتاج مراجعة علمية قبل الاعتماد الرسمي، وخاصة أجوبة المسائل الفقهية الدقيقة. */
window.RQ = window.RQ || {};

RQ.ART.push(
  { id: "a40", t: "Adorar a Dios: mucho más que un rito", tar: "العبادة أوسع من الشعائر", si: ["proposito", "practicas"], st: ["conocer", "cerca"], au: ["general", "indiferente", "buscador", "nuevo"], q: ["51:56", "62:10"], h: ["5348"],
    es: ["Cuando se habla de «adoración», muchos piensan solo en rezar o en ir a un templo. En el islam, la palabra árabe ʿibāda es mucho más amplia: los sabios la definen como todo lo que Dios ama, sean palabras o actos, visibles o del corazón.", "El Corán enseña que fuimos creados para adorar a Dios. Eso no significa pasar el día en la mezquita, sino vivir con Dios presente: el trabajo honrado para mantener a la familia, el estudio, la amabilidad con un vecino o incluso una sonrisa pueden convertirse en adoración cuando se hacen con buena intención.", "Así, la vida entera adquiere sentido. La oración, el ayuno y los demás pilares son los momentos fijos que alimentan esa relación con Dios, y el resto del día la prolonga. Nada bueno es pequeño cuando se hace por Él."],
    ar: "العبادة في الإسلام اسم جامع لكل ما يحبه الله من الأقوال والأعمال الظاهرة والباطنة، ولا تقتصر على الشعائر. خُلقنا لعبادة الله، فالعمل الشريف والتعلم والإحسان إلى الجار والابتسامة عبادة بالنية الصالحة، والشعائر مواعيد ثابتة تغذي هذه الصلة وبقية اليوم امتداد لها." },
  { id: "a41", t: "Los nombres más bellos de Allah", tar: "أسماء الله الحسنى ومعانيها", si: ["dios", "curioso"], st: ["conocer", "cerca"], au: ["general", "catolico", "buscador", "nuevo"], q: ["7:180", "59:22", "42:11"], h: [],
    es: ["El Corán enseña que a Dios pertenecen los nombres más bellos y que podemos invocarle con ellos. Cada nombre revela algo de quién es Él: el Compasivo, el Misericordioso, el Sabio, el Justo, el Perdonador, el Generoso, el Cercano…", "Estos nombres no son simples títulos. Quien sabe que Dios es el Proveedor trabaja sin angustia; quien sabe que es el Perdonador no se hunde en la culpa; quien sabe que lo oye todo habla con Él en cualquier momento y en cualquier idioma.", "Al mismo tiempo, nada se parece a Dios: Sus atributos son perfectos y no se comparan con los de las criaturas. Conocer a Dios por Sus nombres es, para el musulmán, el camino más hermoso para amarle y confiar en Él."],
    ar: "لله الأسماء الحسنى ندعوه بها: الرحمن الرحيم الحكيم العدل الغفور الكريم القريب. وليست ألقابًا مجردة؛ فمن عرف أنه الرزاق عمل بلا قلق، ومن عرف أنه الغفور لم يغرق في الذنب، ومن عرف أنه السميع ناجاه في كل وقت. وليس كمثله شيء، ومعرفته بأسمائه أجمل طريق لمحبته والتوكل عليه." },
  { id: "a42", t: "¿Por qué un solo Dios?", tar: "لماذا إله واحد؟", si: ["dios", "trinidad", "ciencia"], st: ["conocer", "dudas"], au: ["general", "catolico", "protestante", "ateo", "buscador"], q: ["112:1-4", "21:25", "30:30"], h: [],
    es: ["La fe en un único Dios es el corazón del islam. El ser humano siente de forma natural que detrás del orden del universo hay un solo Creador, y el Corán enseña que esa inclinación forma parte de la naturaleza con la que Dios nos creó.", "Un universo tan armonioso, con las mismas leyes en cada rincón, apunta a una sola voluntad que lo gobierna. Dios no necesita socios, ni hijos, ni ayudantes: es el Único, el Eterno, de quien todos dependen y que no depende de nadie.", "Según el Corán, este fue el mensaje de todos los profetas: no hay más dios que Dios, adoradle solo a Él. Creer en un solo Dios libera: el corazón ya no se divide entre ídolos, miedos o personas, sino que se dirige a quien de verdad lo merece."],
    ar: "التوحيد قلب الإسلام، والإنسان يشعر بفطرته أن وراء نظام الكون خالقًا واحدًا. وانسجام الكون ووحدة قوانينه يدلان على إرادة واحدة تدبّره. الله الأحد الصمد لا يحتاج شريكًا ولا ولدًا ولا معينًا، وهذه دعوة كل الأنبياء، والتوحيد يحرر القلب من التعلق بغير الله." },
  { id: "a43", t: "¿Hay vida después de la muerte?", tar: "هل هناك حياة بعد الموت؟", si: ["akhira", "proposito", "ciencia"], st: ["conocer", "dudas"], au: ["ateo", "indiferente", "buscador", "general"], q: ["36:78-79", "23:115", "53:38-39"], h: [],
    es: ["Muchos piensan que la muerte es el final de todo. El islam enseña que no: la vida en este mundo es solo una etapa, y después viene la resurrección, cuando Dios devolverá la vida a todos los seres humanos.", "El Corán responde a quien pregunta cómo pueden revivir unos huesos ya deshechos: los hará revivir Aquel que los creó la primera vez, y Él conoce toda la creación. Si Dios nos dio la existencia desde la nada, devolvérnosla no es más difícil para Él.", "Además, la razón nos dice que la vida no puede ser en vano: muchas injusticias quedan sin reparar aquí y muchos actos buenos pasan sin recompensa. El Corán enseña que cada persona recibirá el fruto de su propio esfuerzo. Esa certeza da sentido y responsabilidad a cada día."],
    ar: "ليس الموتُ النهايةَ، بل الدنيا مرحلة يعقبها البعث. ومن أنشأ العظام أول مرة يحييها وهو بكل خلق عليم، ومن خلقنا من عدم لا يعجزه أن يعيدنا. والعقل يأبى أن تكون الحياة عبثًا والمظالم بلا جزاء، وليس للإنسان إلا ما سعى." },
  { id: "a44", t: "El Paraíso y el Infierno", tar: "الجنة والنار", si: ["akhira", "proposito"], st: ["conocer"], au: ["general", "indiferente", "buscador", "catolico"], q: ["87:16-17", "99:7-8", "4:40"], h: [],
    es: ["El islam enseña que después del Juicio hay dos destinos eternos: el Paraíso, lugar de felicidad completa y de cercanía a Dios, y el Infierno, lugar de castigo para quien rechazó la verdad y se obstinó en el mal.", "La justicia de Dios es perfecta: nada se pierde, ni siquiera el peso de un átomo de bien o de mal. Y Su generosidad es inmensa: multiplica las buenas obras y concede de Su parte una recompensa enorme. Nadie será tratado con injusticia.", "El Corán recuerda que solemos preferir la vida de este mundo, aunque la otra es mejor y más duradera. Pensar en el Paraíso y en el Infierno no es para vivir con miedo, sino para vivir con esperanza, con responsabilidad y con la mirada puesta en lo que permanece."],
    ar: "بعد الحساب داران أبديتان: الجنة دار النعيم والقرب من الله، والنار دار العقاب لمن جحد الحق وأصرّ على الشر. عدل الله تام لا يضيع عنده مثقال ذرة، وكرمه واسع يضاعف الحسنات ويؤتي من لدنه أجرًا عظيمًا. والآخرة خير وأبقى، وتذكّرها يبعث الرجاء والمسؤولية لا الخوف وحده." },
  { id: "a45", t: "Cómo se transmitió el Corán", tar: "كيف نُقل القرآن إلينا؟", si: ["coran", "ciencia"], st: ["conocer", "dudas"], au: ["general", "ateo", "buscador", "catolico", "protestante"], q: ["15:9", "54:17", "4:82"], h: [],
    es: ["El Corán fue revelado al Profeta Muhammad ﷺ poco a poco, a lo largo de unos veintitrés años. Desde el primer día, sus compañeros lo aprendían de memoria, y varios de ellos lo escribían en los materiales de la época, como pieles, huesos o tallos de palmera.", "Tras la muerte del Profeta, el califa Abu Bakr mandó reunir todo el texto escrito en un solo volumen, comprobado por quienes lo sabían de memoria. Años después, el califa Uthmán hizo copias de ese texto y las envió a las principales ciudades. Escritura y memoria se confirmaban mutuamente.", "Esa doble cadena nunca se ha roto: hoy millones de personas memorizan el Corán completo, muchas desde niños, en todos los continentes. El Corán afirma que Dios lo hizo fácil de recordar y que Él mismo lo protege."],
    ar: "نزل القرآن منجّمًا في نحو ثلاث وعشرين سنة، وكان الصحابة يحفظونه ويكتبه بعضهم على الجلود والعظام والجريد. ثم جمعه أبو بكر في مصحف واحد موثَّق بالحفظ، ونسخ عثمان منه مصاحف أرسلها إلى الأمصار. وما زال الحفظ والكتابة يتعاضدان، والملايين يحفظونه، والله يسّره للذكر وتكفّل بحفظه." },
  { id: "a46", t: "El carácter del Profeta Muhammad ﷺ", tar: "أخلاق النبي ﷺ", si: ["profeta"], st: ["conocer", "cerca"], au: ["general", "catolico", "indiferente", "buscador"], q: ["68:4", "9:128", "3:159"], h: ["5803"],
    es: ["El Corán describe al Profeta Muhammad ﷺ como alguien de un carácter magnífico. Quienes convivieron con él contaban que ayudaba en las tareas de la casa, que era tierno con los niños y que trataba con respeto a los pobres y a los débiles.", "El Corán dice también que le dolía lo que hacía sufrir a la gente, que deseaba su bien y que era compasivo con los creyentes. Y explica que, si hubiera sido duro de corazón, la gente se habría alejado de él: su dulzura fue una misericordia de Dios.", "Él mismo enseñó que los mejores de nosotros son los de mejor carácter. Por eso, para un musulmán, seguir al Profeta no es solo rezar como él, sino también hablar, perdonar y tratar a los demás como él lo hacía."],
    ar: "وصف القرآن النبي ﷺ بأنه على خلق عظيم، وكان يعين أهله في البيت ويرفق بالأطفال ويحترم الفقراء والضعفاء. يعزّ عليه ما يشق على الناس، حريص عليهم رحيم بالمؤمنين، ولو كان فظًا لانفضوا من حوله. وعلّم أن خيارنا أحاسننا أخلاقًا، فالاقتداء به يشمل الخلق والمعاملة لا الشعائر وحدها." },
  { id: "a47", t: "Fe y razón", tar: "الإيمان والعقل", si: ["ciencia", "dios"], st: ["conocer", "dudas"], au: ["ateo", "buscador", "indiferente", "general"], q: ["2:164", "52:35", "88:17-20", "17:36"], h: [],
    es: ["Hay quien cree que tener fe significa dejar de pensar. El Corán propone lo contrario: invita una y otra vez a reflexionar, a observar el cielo, la tierra, la lluvia o los animales, y dice que en todo ello hay signos para quienes razonan.", "Plantea preguntas directas a la razón: ¿fuimos creados de la nada, o somos nosotros los creadores? Y pide no seguir aquello de lo que no se tiene conocimiento. La fe, en el islam, se apoya en la reflexión y no en la imposición.", "Por eso los musulmanes no vemos conflicto entre la fe y la razón bien usada. La razón descubre los signos; la revelación explica su sentido y nos dice lo que la razón sola no puede alcanzar: quién es Dios y para qué vivimos."],
    ar: "يظن بعضهم أن الإيمان تعطيل للعقل، والقرآن يدعو مرارًا إلى التفكر في السماء والأرض والمطر والإبل، ففيها آيات لقوم يعقلون. ويسأل العقل: أم خُلقوا من غير شيء أم هم الخالقون؟ وينهى عن اتباع ما ليس لنا به علم. فالعقل يكتشف الآيات، والوحي يبيّن معناها وما لا يدركه العقل وحده." },
  { id: "a48", t: "Cuando tus padres no son musulmanes", tar: "حين لا يكون والداك مسلمَين", si: ["familia", "presion", "primeros"], st: ["nuevo"], au: ["nuevo"], q: ["31:14-15", "17:24"], h: ["5866"],
    es: ["Muchos nuevos musulmanes temen que su decisión los aleje de su familia. El islam enseña justo lo contrario: tus padres siguen siendo tus padres, y el Corán manda acompañarlos en este mundo con bondad, aunque no compartan tu fe.", "Solo hay un límite: no obedecer a nadie en algo que vaya contra Dios. Fuera de eso, visítalos, ayúdalos, llámalos, ten paciencia si reaccionan con miedo o enfado, y pide a Dios que tenga misericordia de ellos como ellos te cuidaron cuando eras pequeño.", "No hace falta explicarlo todo el primer día. Con frecuencia, lo que más convence a una familia no son los argumentos, sino ver que su hijo o su hija se ha vuelto más respetuoso, más cariñoso y más responsable. La religión es facilidad: avanza con calma."],
    ar: "يخشى بعض المسلمين الجدد أن يبعدهم إسلامهم عن أهلهم، والإسلام يأمر بمصاحبة الوالدين في الدنيا بالمعروف وإن لم يكونا مسلمَين، ولا طاعة لأحد في معصية الله. زرهما وأعنهما واصبر على خوفهما وغضبهما، وادعُ لهما بالرحمة كما ربّياك صغيرًا. وأكثر ما يقنع الأهل حسن الخلق، والدين يسر فتدرّج." },
  { id: "a49", t: "El vecino en el islam", tar: "الجار في الإسلام", si: ["familia", "curioso"], st: ["contacto", "conocer"], au: ["general", "indiferente", "catolico", "protestante"], q: ["4:36"], h: ["66520", "5437"],
    es: ["El Corán, en el mismo versículo en que ordena adorar solo a Dios y tratar bien a los padres, manda hacer el bien al vecino pariente y al vecino que no lo es. El vecino tiene en el islam derechos reales, sea cual sea su religión.", "En la práctica, ser buen vecino es saludar, ayudar cuando hace falta, compartir algo de comida, visitar al enfermo y no causar molestias ni daño. El Profeta ﷺ enseñó que nadie tiene una fe completa hasta que desea para su hermano lo que desea para sí mismo, y que quien cree en Dios dice el bien o calla.", "Muchos musulmanes, al mudarse, llevan un dulce a sus nuevos vecinos o los invitan en las fiestas. Pequeños gestos así dicen más del islam que muchos discursos."],
    ar: "قرن القرآن الأمر بعبادة الله والإحسان إلى الوالدين بالإحسان إلى الجار ذي القربى والجار الجنب، فللجار حقوق أيًّا كان دينه: السلام والعون والهدية وعيادة المريض وكف الأذى. ولا يؤمن أحدنا حتى يحب لأخيه ما يحب لنفسه، ومن آمن بالله فليقل خيرًا أو ليصمت. والهدية الصغيرة للجيران أبلغ من خطب كثيرة." },
  { id: "a50", t: "La peregrinación a La Meca", tar: "الحج إلى مكة", si: ["practicas", "curioso"], st: ["conocer"], au: ["general", "catolico", "indiferente", "buscador"], q: ["2:127", "22:78", "49:13"], h: ["66512"],
    es: ["La peregrinación (Hajj) es el quinto pilar del islam. Es obligatoria una vez en la vida para todo musulmán adulto que tenga salud y medios para realizarla, y se hace en días fijos del último mes del calendario islámico.", "Sus ritos recuerdan a Abraham y a su familia: el Corán narra cómo Abraham e Ismael levantaron los cimientos de la Kaaba, la casa dedicada a adorar al Dios único. Los peregrinos rezan, recuerdan a Dios y piden perdón en los mismos lugares desde hace siglos.", "Durante la peregrinación, los hombres visten dos telas blancas sencillas, y ricos y pobres, de todos los colores y lenguas, se ponen hombro con hombro. Es una imagen viva de lo que enseña el Corán: lo que nos distingue ante Dios no es la raza ni el dinero, sino la piedad."],
    ar: "الحج الركن الخامس، يجب مرة في العمر على المسلم البالغ المستطيع، في أيام معلومة من شهر ذي الحجة. شعائره تذكّر بإبراهيم وأهله، فقد رفع مع إسماعيل قواعد الكعبة. يلبس الرجال إزارًا ورداءً أبيضين، ويقف الغني والفقير من كل لون ولسان جنبًا إلى جنب، فلا تفاضل إلا بالتقوى." },
  { id: "a51", t: "Las dos fiestas del islam", tar: "عيدا المسلمين", si: ["ocasion", "practicas"], st: ["contacto", "conocer", "nuevo"], au: ["general", "catolico", "indiferente", "nuevo"], q: ["2:185", "76:8-9"], h: [],
    es: ["Los musulmanes tienen dos grandes fiestas al año. La primera, Eid al-Fitr, llega al terminar el mes de Ramadán: es la alegría de haber completado el ayuno y de agradecer a Dios Su guía.", "La segunda, Eid al-Adha o fiesta del sacrificio, coincide con los días de la peregrinación y recuerda la entrega de Abraham a Dios. Muchas familias sacrifican un animal y reparten parte de la carne entre familiares, vecinos y personas necesitadas.", "Ambas fiestas empiezan con una oración en comunidad por la mañana y continúan con visitas, ropa nueva, regalos para los niños y comidas compartidas. En el Eid al-Fitr, además, se da una caridad especial para que nadie pase ese día con hambre. Una sonrisa y un «Eid Mubarak» siempre son bienvenidos."],
    ar: "للمسلمين عيدان: عيد الفطر بعد إكمال صيام رمضان فرحًا بالطاعة وتكبيرًا لله على هدايته، وعيد الأضحى في أيام الحج تذكيرًا بإسلام إبراهيم لله، وفيه تُذبح الأضاحي ويوزَّع من لحمها على الأهل والجيران والمحتاجين. يبدآن بصلاة جماعية صباحًا ثم الزيارات والهدايا، وفي الفطر زكاة الفطر حتى لا يجوع أحد يوم العيد." },
  { id: "a52", t: "Mujeres que marcaron la historia del islam", tar: "نساء في تاريخ الإسلام", si: ["mujer"], st: ["conocer", "dudas"], au: ["general", "indiferente", "catolico", "buscador"], q: ["33:35", "16:97"], h: [],
    es: ["La primera persona que creyó en el Profeta Muhammad ﷺ fue una mujer: su esposa Jadiya, una comerciante respetada de La Meca que lo apoyó con su fe, su consejo y sus bienes en los años más difíciles.", "Más tarde, Aisha se convirtió en una de las grandes sabias de su tiempo: transmitió una parte importante de las enseñanzas del Profeta, y los compañeros acudían a ella para consultarle cuestiones de religión. A lo largo de la historia hubo muchas mujeres maestras del hadiz, de la jurisprudencia y de otras ciencias.", "El Corán menciona a hombres y mujeres por igual al describir a los creyentes que oran, ayunan, dan caridad y recuerdan a Dios, y les promete la misma recompensa. Estas mujeres no fueron una excepción, sino el fruto de esa enseñanza."],
    ar: "أول من آمن بالنبي ﷺ امرأة: خديجة التاجرة الموقّرة في مكة التي آزرته بإيمانها ورأيها ومالها في أشد السنين. وكانت عائشة من كبار علماء عصرها، روت جانبًا كبيرًا من السنة ورجع إليها الصحابة. وفي التاريخ عالمات كثيرات في الحديث والفقه. والقرآن يذكر المؤمنين والمؤمنات معًا ويعدهم الأجر نفسه." },
  { id: "a53", t: "La justicia, un mandato de Dios", tar: "العدل أمر إلهي", si: ["violencia", "curioso", "religiones"], st: ["conocer"], au: ["general", "indiferente", "ateo", "catolico"], q: ["16:90", "4:58", "4:135", "5:8"], h: [],
    es: ["La justicia ocupa un lugar central en el islam. El Corán dice que Dios ordena la justicia y el buen trato, y manda devolver lo confiado a sus dueños y juzgar con equidad entre la gente.", "No se trata de una justicia selectiva. El Corán pide mantenerse firmes en la justicia aunque sea contra uno mismo, contra los padres o contra los parientes, sea el otro rico o pobre. Y añade que la aversión hacia un grupo no debe llevarnos a ser injustos con él.", "Para el musulmán, ser justo en el trabajo, en la familia, en un negocio o en una discusión es parte de su fe. La injusticia, en cambio, es algo que Dios aborrece, venga de quien venga y vaya contra quien vaya."],
    ar: "للعدل مكانة مركزية؛ فالله يأمر بالعدل والإحسان وبأداء الأمانات إلى أهلها والحكم بين الناس بالعدل. وهو عدل غير انتقائي: ولو على أنفسنا أو الوالدين والأقربين، غنيًا كان أو فقيرًا، ولا يحملنا بغض قوم على ألا نعدل. فالعدل في العمل والأسرة والتجارة والخلاف من الإيمان، والظلم يبغضه الله من أي أحد كان." },
  { id: "a54", t: "La paciencia: fuerza en la dificultad", tar: "الصبر قوة في الشدة", si: ["sufrimiento", "enfermedad", "felicidad"], st: ["conocer", "cerca"], au: ["general", "indiferente", "buscador", "nuevo"], q: ["2:153", "2:155", "39:10"], h: ["3553"],
    es: ["La paciencia (sabr) no es resignación pasiva. En el islam significa mantenerse firme: no desesperar ante la desgracia, perseverar en el bien y contenerse ante lo que hace daño. El Corán pide buscar ayuda en la paciencia y en la oración, y dice que Dios está con los pacientes.", "Dios anuncia que pondrá a prueba al ser humano con algo de miedo, de hambre y de pérdida de bienes, de vidas y de frutos, y da la buena noticia a los pacientes. Y promete que los pacientes recibirán su recompensa sin medida.", "El Profeta ﷺ enseñó que ningún cansancio, enfermedad, preocupación o tristeza que sufre el creyente queda sin valor: Dios borra con ello sus faltas. Por eso el creyente puede llorar y sentir dolor y, al mismo tiempo, tener el corazón en paz."],
    ar: "الصبر ليس استسلامًا سلبيًا، بل ثبات: لا يأس عند المصيبة، ومداومة على الخير، وكفّ للنفس عما يضر. نستعين بالصبر والصلاة، والله مع الصابرين. يبتلينا الله بشيء من الخوف والجوع ونقص الأموال والأنفس والثمرات ويبشّر الصابرين، ويوفّيهم أجرهم بغير حساب. وما يصيب المؤمن من تعب أو مرض أو هم أو حزن إلا كفّر الله به من خطاياه." },
  { id: "a55", t: "La sinceridad y la palabra dada", tar: "الصدق والوفاء بالكلمة", si: ["familia", "practicas"], st: ["conocer", "cerca"], au: ["general", "indiferente", "ateo", "nuevo"], q: ["9:119", "61:2-3"], h: [],
    es: ["Antes de recibir la revelación, la gente de La Meca llamaba a Muhammad ﷺ «el confiable». Incluso muchos de quienes rechazaban su mensaje le dejaban en depósito sus objetos de valor. La honradez fue la base de su credibilidad.", "El Corán pide a los creyentes ser conscientes de Dios y estar con los sinceros, y les reprocha decir lo que no hacen. La sinceridad en el islam abarca la palabra, las promesas, los contratos y también la intención del corazón.", "Una persona veraz puede equivocarse, pero no engaña. En un mundo lleno de apariencias, cumplir lo que se dice es una de las formas más claras de mostrar lo que es el islam."],
    ar: "قبل البعثة لقّب أهل مكة محمدًا ﷺ بالأمين، وكان كثير ممن رفضوا رسالته يودعونه أماناتهم، فكانت الأمانة أساس مصداقيته. والقرآن يأمر بتقوى الله والكون مع الصادقين، وينكر أن نقول ما لا نفعل. والصدق يشمل القول والوعد والعقد والنية، والصادق قد يخطئ لكنه لا يخدع، والوفاء بالكلمة من أوضح صور الدعوة." },
  { id: "a56", t: "La muerte: un recuerdo que da vida", tar: "الموت: تذكرة تحيي القلب", si: ["akhira", "duelo", "proposito"], st: ["conocer", "cerca"], au: ["general", "indiferente", "buscador", "ateo"], q: ["3:185", "55:26-27", "67:2", "2:156"], h: [],
    es: ["Es el único hecho seguro de la vida y, sin embargo, intentamos no pensar en él. El Corán lo recuerda con serenidad: toda alma probará la muerte, y todo lo que hay en la tierra desaparecerá, mientras permanece el rostro de nuestro Señor.", "El Corán explica que Dios creó la muerte y la vida para probarnos y ver quién obra mejor. Recordar la muerte no es una idea triste, sino una forma de ordenar las prioridades: perdonar antes, agradecer más y no dejar para mañana el bien.", "Ante la pérdida de un ser querido, el musulmán dice que pertenecemos a Dios y que a Él volveremos. Esas palabras no quitan el dolor, pero le dan sentido: la separación no es para siempre, y el encuentro con Dios es el destino de todos."],
    ar: "الموت الحقيقة المؤكدة التي نتهرب من التفكير فيها، والقرآن يذكّر بها بسكينة: كل نفس ذائقة الموت، وكل من عليها فان ويبقى وجه ربك. خلق الله الموت والحياة ليبلونا أينا أحسن عملًا، فذكر الموت يرتّب الأولويات: نعفو أسرع ونشكر أكثر ولا نؤجل الخير. وعند الفقد نقول: إنا لله وإنا إليه راجعون." },
  { id: "a57", t: "El arrepentimiento: siempre se puede volver", tar: "التوبة: الباب المفتوح دائمًا", si: ["perdon", "felicidad"], st: ["conocer", "cerca", "nuevo"], au: ["general", "indiferente", "buscador", "nuevo", "catolico"], q: ["3:135", "4:110", "39:53", "25:70"], h: ["4302"],
    es: ["Todos nos equivocamos. La pregunta no es si caeremos, sino qué hacemos después. El islam enseña que la puerta de Dios está siempre abierta: quien hace un mal y luego pide perdón a Dios, encuentra a Dios Perdonador y Misericordioso.", "El arrepentimiento (tawba) es sencillo y directo, sin intermediarios ni confesión ante otra persona: lamentar lo hecho, dejarlo, decidir no volver a hacerlo y, si se perjudicó a alguien, devolverle su derecho. El Corán dice incluso que Dios cambia por buenas las malas obras de quien se arrepiente, cree y obra bien.", "Por eso el Corán llama a no desesperar nunca de la misericordia de Dios, que perdona todos los pecados. Y el Profeta ﷺ aconsejó que, tras un error, hagamos una buena obra que lo borre, y que tratemos a la gente con buen carácter."],
    ar: "كلنا نخطئ، والسؤال ماذا نفعل بعد الخطأ. باب الله مفتوح: من عمل سوءًا ثم استغفر الله وجد الله غفورًا رحيمًا. والتوبة مباشرة بلا وسيط ولا اعتراف لبشر: ندم وإقلاع وعزم على عدم العودة ورد الحقوق إلى أهلها، والله يبدّل سيئات التائب حسنات. فلا قنوط من رحمة الله، وأتبع السيئة الحسنة تمحها وخالق الناس بخلق حسن." },
  { id: "a58", t: "Abraham y el argumento de los astros", tar: "إبراهيم وحجة الكواكب", si: ["dios", "religiones", "ciencia"], st: ["conocer", "dudas"], au: ["buscador", "ateo", "catolico", "protestante"], q: ["6:76-79", "4:125", "16:120"], h: [],
    es: ["El Corán cuenta que Abraham (la paz sea con él) vivía entre gente que adoraba ídolos y astros, y quiso mostrarles su error con un razonamiento sencillo. Al ver una estrella por la noche dijo: «¿Este es mi Señor?»; pero cuando se ocultó, declaró que no ama a lo que desaparece.", "Hizo lo mismo con la luna y con el sol: todo lo que cambia, sale y se pone depende de otro y no puede ser Dios. Al final proclamó que dirigía su rostro, con sinceridad, hacia Aquel que creó los cielos y la tierra, y que se apartaba de toda adoración falsa.", "Por su fe firme y su entrega, Dios lo tomó como amigo íntimo (Jalil), y el Corán lo presenta como un modelo de fe. Su historia nos invita a lo mismo: mirar el mundo con honestidad y buscar al Creador que está detrás de todo."],
    ar: "يقص القرآن أن إبراهيم عليه السلام عاش بين قوم يعبدون الأصنام والكواكب، فأراد أن يبيّن لهم خطأهم بحجة واضحة: رأى كوكبًا فقال: هذا ربي؟ فلما أفل قال: لا أحب الآفلين، وكذلك القمر والشمس، فكل ما يتغير ويغيب محتاج إلى غيره لا يكون ربًا، ثم وجّه وجهه حنيفًا للذي فطر السماوات والأرض وبرئ من الشرك. فاتخذه الله خليلًا وجعله أمة قانتًا، وقصته دعوة إلى النظر الصادق في الكون والبحث عن خالقه." },
  { id: "a59", t: "Moisés: valor y confianza en Dios", tar: "موسى: الشجاعة والثقة بالله", si: ["religiones", "sufrimiento", "felicidad"], st: ["conocer"], au: ["general", "catolico", "protestante", "buscador"], q: ["20:25-28", "20:44", "20:46", "26:61-62"], h: [],
    es: ["Moisés (la paz sea con él) es el profeta cuyo nombre más se repite en el Corán. Dios lo envió al Faraón, el gobernante más poderoso de su tiempo, y Moisés, consciente de su debilidad, pidió a Dios que le abriera el pecho, le facilitara la misión y le soltara la lengua.", "Dios les ordenó a él y a su hermano Aarón hablar al Faraón con palabras suaves, por si reflexionaba. Y cuando sintieron miedo, les dijo que no temieran, porque Él estaba con ellos, oyendo y viendo.", "Cuando su pueblo quedó atrapado entre el mar y el ejército, algunos creyeron que estaban perdidos. Moisés respondió con certeza que su Señor estaba con él y lo guiaría. Su historia enseña a hablar con suavidad incluso al tirano, y a confiar en Dios cuando todas las salidas parecen cerradas."],
    ar: "موسى عليه السلام أكثر الأنبياء ذكرًا باسمه في القرآن، أرسله الله إلى فرعون أقوى حكام زمانه، فدعا: رب اشرح لي صدري ويسر لي أمري واحلل عقدة من لساني. وأمره الله وهارون أن يقولا له قولًا لينًا، وطمأنهما: لا تخافا إنني معكما أسمع وأرى. وحين حوصر قومه بين البحر والجيش قال: كلا إن معي ربي سيهدين." },
  { id: "a60", t: "Jesús, el Mesías: sus milagros y su mensaje", tar: "المسيح عيسى: معجزاته ورسالته", si: ["jesus", "trinidad"], st: ["conocer", "dudas"], au: ["catolico", "protestante"], q: ["3:49", "3:51", "5:75", "61:6"], h: [],
    es: ["El Corán relata muchos milagros de Jesús (la paz sea con él): curó al ciego de nacimiento y al leproso, y devolvió la vida a los muertos, siempre con el permiso de Dios. Los musulmanes creemos en todos ellos con amor.", "Que todo ocurriera con el permiso de Dios es la clave: los milagros mostraban que Jesús era un auténtico mensajero, y su mensaje era claro: Dios es mi Señor y vuestro Señor, adoradle; ese es el camino recto. El Corán recuerda también que Jesús y su madre comían alimentos, como todos los seres humanos.", "Según el Corán, Jesús anunció además la llegada de un mensajero después de él. Para el musulmán, amar a Jesús significa seguir lo que él enseñó: adorar solo a Dios."],
    ar: "يذكر القرآن معجزات عيسى عليه السلام: أبرأ الأكمه والأبرص وأحيا الموتى بإذن الله، ونؤمن بها كلها بمحبة. وكونها بإذن الله دليل على أنه رسول صادق، ودعوته: إن الله ربي وربكم فاعبدوه هذا صراط مستقيم. وكان هو وأمه يأكلان الطعام، وبشّر برسول يأتي من بعده، ومحبته اتباع ما دعا إليه من عبادة الله وحده." },
  { id: "a61", t: "María: confianza en Dios en la prueba", tar: "مريم: الثقة بالله في الشدة", si: ["jesus", "mujer", "sufrimiento"], st: ["contacto", "conocer"], au: ["catolico", "general"], q: ["19:16-21", "19:23-26", "3:42"], h: [],
    es: ["El Corán narra que un ángel se presentó a María (la paz sea con ella) para anunciarle un hijo puro. Ella, sorprendida, preguntó cómo podría tener un hijo si ningún hombre la había tocado, y el ángel le respondió que eso es fácil para Dios.", "Cuando llegaron los dolores del parto, María se retiró sola junto al tronco de una palmera, angustiada. Entonces fue consolada: no debía entristecerse, pues Dios había puesto un arroyo a sus pies, y si sacudía la palmera caerían dátiles frescos. Debía comer, beber y tranquilizarse.", "Es una escena de enorme ternura: Dios cuida a María en el momento más difícil de su vida. El Corán la presenta como elegida y purificada, y su historia consuela a toda persona que atraviesa una prueba en soledad."],
    ar: "يقص القرآن أن الملَك بشّر مريم عليها السلام بغلام زكي، فعجبت كيف يكون لها ولد ولم يمسسها بشر، فقيل لها: هو على الله هيّن. ولما ألجأها المخاض وحدها إلى جذع النخلة نوديت ألا تحزن، فقد جعل ربها تحتها نهرًا صغيرًا، وتساقط عليها النخلة رطبًا جنيًا، فلتأكل ولتشرب ولتقرّ عينًا. مشهد رحمة بامرأة اصطفاها الله وطهرها، وعزاء لكل مبتلى وحيد." },
  { id: "a62", t: "Destino y libertad: lo básico", tar: "القدر والاختيار: الأساسيات", si: ["dios", "sufrimiento", "ciencia"], st: ["conocer", "dudas"], au: ["general", "buscador", "ateo", "catolico", "protestante"], q: ["76:2-3", "64:11", "2:286"], h: [],
    es: ["Creer en el decreto divino (qadar) es uno de los seis pilares de la fe. Significa que Dios lo sabe todo, que nada ocurre en el universo fuera de Su voluntad y que nada nos sucede sin Su permiso.", "Al mismo tiempo, el ser humano no es una marioneta. El Corán explica que Dios nos dio oído y vista, y nos mostró el camino: cada uno decide si es agradecido o ingrato. Por eso somos responsables de nuestros actos, y Dios no exige a nadie más de lo que puede.", "Que Dios sepa de antemano lo que vamos a elegir no nos obliga a elegirlo. Como nadie sabe lo que está escrito para él, nuestra tarea es clara: esforzarnos, hacer el bien, pedir ayuda a Dios y aceptar con serenidad lo que no depende de nosotros. Los detalles de este tema conviene estudiarlos con un sabio de confianza."],
    ar: "الإيمان بالقدر من أركان الإيمان الستة: الله يعلم كل شيء، ولا يقع شيء إلا بمشيئته، ولا تصيبنا مصيبة إلا بإذنه. والإنسان مع ذلك ليس مجبورًا؛ فقد جعله الله سميعًا بصيرًا وهداه السبيل إما شاكرًا وإما كفورًا، فهو مسؤول، ولا يكلف الله نفسًا إلا وسعها. وعلم الله السابق لا يجبرنا، فعلينا السعي والاستعانة بالله والرضا، وتؤخذ التفاصيل عن أهل العلم." },
  { id: "a63", t: "El islam y el cuidado de la tierra", tar: "الإسلام والعناية بالأرض", si: ["ciencia", "practicas"], st: ["contacto", "conocer"], au: ["general", "ateo", "indiferente", "buscador"], q: ["2:164", "7:56", "7:31"], h: [],
    es: ["El Corán presenta la naturaleza como un conjunto de signos de Dios: la lluvia que da vida a la tierra seca, los animales, los vientos y las nubes. Quien la contempla con atención encuentra en ella motivos de gratitud y de reflexión.", "El ser humano no es dueño absoluto de la tierra, sino responsable ante Dios de cómo la usa. El Corán pide no corromper la tierra después de que Dios la puso en orden, y no derrochar: comer y beber, pero sin excesos.", "De ahí nacen actitudes muy concretas: no desperdiciar el agua aunque abunde, no maltratar a los animales, plantar y cuidar, no contaminar lo que otros necesitan. Cuidar la creación es, para el musulmán, una forma de agradecer al Creador."],
    ar: "يقدّم القرآن الطبيعة آيات لله: المطر يحيي الأرض بعد موتها، والدواب والرياح والسحاب. والإنسان ليس مالكًا مطلقًا للأرض بل مسؤول أمام الله عن استعمالها، فلا يفسد فيها بعد إصلاحها ولا يسرف. ومن ذلك ترك الإسراف في الماء ولو كثر، والرفق بالحيوان، والغرس، وعدم التلويث، فرعاية الخلق شكر للخالق." },
  { id: "a64", t: "Honradez en el comercio", tar: "الأمانة في التجارة", si: ["practicas", "familia"], st: ["conocer"], au: ["general", "indiferente", "ateo", "nuevo"], q: ["62:10", "4:58", "9:119"], h: [],
    es: ["El Profeta Muhammad ﷺ trabajó como comerciante antes de recibir la revelación y era conocido por su honradez. El islam no ve el comercio como algo opuesto a la fe: ganarse la vida es digno, y el Corán anima a buscar el sustento que Dios concede.", "Pero el negocio tiene reglas morales: no engañar en el peso ni en la calidad, no ocultar defectos, no mentir para vender, cumplir los contratos y pagar a tiempo lo que se debe. El Corán manda devolver lo confiado a sus dueños y estar con los sinceros.", "Muchos pueblos de Asia y de África conocieron el islam a través de comerciantes musulmanes que trataban con justicia. Un precio justo y una palabra cumplida siguen siendo hoy una invitación silenciosa al islam."],
    ar: "عمل النبي ﷺ بالتجارة قبل البعثة وعُرف بالأمانة، والإسلام لا يرى التجارة نقيضًا للإيمان، فطلب الرزق شريف والقرآن يحث على ابتغاء فضل الله. لكن للتجارة أخلاقًا: لا غش في الكيل والجودة، ولا كتمان للعيب، ولا كذب للبيع، ووفاء بالعقود وأداء للحقوق في وقتها. وقد عرفت شعوب في آسيا وإفريقيا الإسلام عن طريق تجار أمناء." },
  { id: "a65", t: "El viernes y la mezquita", tar: "يوم الجمعة والمسجد", si: ["practicas", "curioso"], st: ["contacto", "conocer", "nuevo"], au: ["general", "catolico", "nuevo", "indiferente"], q: ["62:9", "62:10"], h: [],
    es: ["El viernes es el día de reunión semanal de los musulmanes. Al mediodía, los hombres acuden a la mezquita para escuchar un breve sermón (jutba) y rezar juntos, y las mujeres también pueden asistir. El Corán pide dejar el comercio en ese momento y acudir al recuerdo de Dios.", "Sin embargo, el viernes no es un día de descanso obligatorio: terminada la oración, el Corán invita a dispersarse por la tierra y buscar el favor de Dios, es decir, a volver al trabajo y a la vida diaria.", "La mezquita, por su parte, no es solo un lugar de oración: es un espacio de aprendizaje, de encuentro y de ayuda a la comunidad. Muchas mezquitas abren sus puertas a quien quiera conocerlas, y visitar una es una buena manera de empezar a conocer el islam."],
    ar: "الجمعة يوم الاجتماع الأسبوعي؛ يحضر الرجال ظهرًا إلى المسجد لسماع خطبة قصيرة والصلاة جماعة، ويجوز للنساء الحضور، ويأمر القرآن بترك البيع والسعي إلى ذكر الله. وليست يوم عطلة واجبة، فبعد الصلاة ننتشر في الأرض ونبتغي من فضل الله. والمسجد مكان للتعلم واللقاء وخدمة المجتمع، وزيارته بداية طيبة للتعرف على الإسلام." },
  { id: "a66", t: "El azaque y la caridad", tar: "الزكاة والصدقة", si: ["practicas", "familia"], st: ["conocer"], au: ["general", "indiferente", "catolico", "nuevo"], q: ["2:261", "2:263", "76:8-9"], h: ["66512"],
    es: ["El azaque (zakat) es el tercer pilar del islam: una contribución anual obligatoria, en general del 2,5 % del ahorro que supera un mínimo y se ha conservado durante un año lunar, destinada a los pobres y a las demás categorías de beneficiarios que señala el Corán. No es un favor, sino un derecho que Dios dio a los necesitados sobre la riqueza.", "Además del azaque existe la caridad voluntaria (sadaqa), que se puede dar en cualquier momento y en cualquier cantidad. El Corán la compara con un grano que produce siete espigas con cien granos cada una: Dios multiplica lo que se da con sinceridad.", "La forma también importa: el Corán enseña que una palabra amable vale más que una limosna seguida de ofensa. El creyente da por amor a Dios, sin esperar recompensa ni agradecimiento de quien recibe."],
    ar: "الزكاة الركن الثالث: حق سنوي واجب، غالبًا ربع العشر من المال البالغ نصابًا الذي حال عليه الحول الهجري، يُصرف للفقراء وسائر المستحقين، وهو حق لهم لا منّة. وهناك الصدقة التطوعية في كل وقت وبأي مقدار، مثلها كحبة أنبتت سبع سنابل في كل سنبلة مائة حبة. وقول معروف خير من صدقة يتبعها أذى، والمؤمن يعطي لوجه الله لا يريد جزاءً ولا شكورًا." },
  { id: "a67", t: "Los ángeles y los pilares de la fe", tar: "الملائكة وأركان الإيمان", si: ["curioso", "dios", "primeros"], st: ["conocer", "nuevo"], au: ["general", "buscador", "nuevo", "catolico"], q: ["2:285", "4:136"], h: [],
    es: ["La fe del musulmán se apoya en seis pilares: creer en Dios, en Sus ángeles, en Sus libros revelados, en Sus mensajeros, en el Último Día y en el decreto divino, con lo bueno y lo malo que trae. El Corán describe a los creyentes como quienes creen en todo ello sin hacer distinción entre los mensajeros.", "Los ángeles son criaturas de Dios creadas de luz, que no desobedecen Sus órdenes. Entre ellos está Gabriel (Yibril), que transmitió la revelación a los profetas. Los musulmanes no rezan a los ángeles ni les piden nada: solo se adora a Dios.", "Creer en lo que no vemos no es irracional: aceptamos muchas realidades invisibles por sus efectos o por un testimonio fiable. Para el creyente, la revelación es ese testimonio, y estos seis pilares ofrecen una visión completa de la existencia."],
    ar: "أركان الإيمان ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، والمؤمنون لا يفرقون بين أحد من رسله. والملائكة خلق من نور لا يعصون الله، منهم جبريل الموكّل بالوحي، ولا يُعبدون ولا يُدعون من دون الله. والإيمان بالغيب لا يناقض العقل، فنحن نقبل حقائق غائبة بآثارها أو بخبر صادق، والوحي هو الخبر الصادق." },
  { id: "a68", t: "La palabra buena", tar: "الكلمة الطيبة شجرة مثمرة", si: ["familia", "felicidad"], st: ["contacto", "conocer", "cerca"], au: ["general", "indiferente", "ateo", "nuevo"], q: ["14:24-25"], h: ["5437", "5348"],
    es: ["El Corán compara la palabra buena con un árbol bueno: sus raíces son firmes, sus ramas llegan al cielo y da fruto en todo momento con el permiso de su Señor. Una frase amable puede seguir dando fruto durante años.", "Por eso el islam cuida mucho la lengua. El Profeta ﷺ enseñó que quien cree en Dios y en el Último Día debe decir el bien o callar, y que incluso sonreír a tu hermano es una caridad.", "Saludar, agradecer, pedir perdón, animar a quien está triste, no hablar mal de los ausentes: son actos sencillos que cuestan poco y valen mucho ante Dios. A veces, la mejor manera de hablar del islam es, simplemente, hablar bien."],
    ar: "شبّه القرآن الكلمة الطيبة بشجرة طيبة أصلها ثابت وفرعها في السماء تؤتي أكلها كل حين بإذن ربها. ولذلك يعتني الإسلام باللسان: من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت، وتبسمك في وجه أخيك صدقة. والسلام والشكر والاعتذار وتشجيع الحزين وترك الغيبة أعمال يسيرة عظيمة عند الله، وأحيانًا تكون أفضل دعوة أن تُحسن الكلام." },
  { id: "a69", t: "Una sola humanidad: no al racismo", tar: "إنسانية واحدة: لا للعنصرية", si: ["religiones", "curioso", "violencia"], st: ["contacto", "conocer"], au: ["general", "indiferente", "ateo", "catolico"], q: ["17:70", "49:13"], h: ["4555"],
    es: ["El Corán afirma que Dios honró a los hijos de Adán, a todos, sin distinción de raza, lengua o color. La dignidad humana no se gana ni se compra: es un regalo de Dios a cada persona.", "También enseña que Dios nos creó de un hombre y una mujer y nos hizo pueblos y tribus para que nos conozcamos, no para despreciarnos. Lo que hace a alguien más noble ante Dios no es su origen, sino su piedad, y solo Dios conoce los corazones.", "En la mezquita, el rico y el pobre, el blanco y el negro rezan en la misma fila. Uno de los compañeros más queridos del Profeta ﷺ, Bilal, era un antiguo esclavo de origen etíope, y fue elegido para hacer el llamado a la oración. El racismo no tiene lugar en el islam."],
    ar: "كرّم الله بني آدم جميعًا دون تمييز بعِرق أو لسان أو لون، فالكرامة الإنسانية هبة من الله لا تُشترى. وخلقنا من ذكر وأنثى وجعلنا شعوبًا وقبائل لنتعارف لا لنتحاقر، وأكرمنا عنده أتقانا، والله وحده يعلم القلوب. وفي المسجد يقف الغني والفقير والأبيض والأسود في صف واحد، وكان بلال الحبشي المولى المعتَق مؤذن النبي ﷺ." },
  { id: "a70", t: "Dominar la ira", tar: "ضبط الغضب", si: ["familia", "felicidad"], st: ["conocer", "cerca"], au: ["general", "indiferente", "ateo", "nuevo"], q: ["41:34"], h: ["5351"],
    es: ["La ira es una emoción humana, pero dejarse llevar por ella destruye familias, amistades y oportunidades. El Profeta ﷺ enseñó que el fuerte no es quien derriba a otros en la lucha, sino quien se domina cuando se enfada.", "El Corán va todavía más lejos: pide responder al mal con lo que es mejor, y explica que así quien era tu enemigo puede convertirse en un amigo cercano. No es debilidad, sino una fuerza interior que pocos alcanzan.", "El Profeta ﷺ enseñó pasos sencillos para calmarse: buscar refugio en Dios contra Satanás, guardar silencio y, si uno está de pie, sentarse. Y, sobre todo, recordar que perdonar acerca a la misericordia de Dios."],
    ar: "الغضب انفعال بشري، لكن الانقياد له يهدم الأسر والصداقات والفرص. ليس الشديد بالصرعة، إنما الشديد الذي يملك نفسه عند الغضب. والقرآن يأمر بالدفع بالتي هي أحسن فيصير العدو كأنه ولي حميم، وتلك قوة لا ضعف. ومن وسائل التهدئة في السنة الاستعاذة بالله من الشيطان والسكوت وتغيير الهيئة كأن يجلس القائم، والعفو يقرّب من رحمة الله." },
  { id: "a71", t: "Ansiedad y paz interior", tar: "القلق وطمأنينة القلب", si: ["felicidad", "sufrimiento"], st: ["contacto", "conocer", "cerca"], au: ["general", "indiferente", "buscador", "ateo", "nuevo"], q: ["13:28", "94:5-6", "20:25-28", "65:2-3"], h: [],
    es: ["Vivimos más conectados que nunca y, sin embargo, muchas personas se sienten solas, cansadas y ansiosas. El islam no niega esas emociones ni sustituye la ayuda médica cuando hace falta, pero ofrece algo profundo: una relación diaria con Dios.", "El Corán afirma que los corazones encuentran sosiego en el recuerdo de Dios, y recuerda que junto a la dificultad viene la facilidad. Moisés, ante una misión enorme, pidió a Dios que le abriera el pecho y le facilitara su tarea: es una súplica que cualquiera puede repetir.", "Confiar en Dios no significa dejar de actuar, sino hacer lo que está en nuestras manos y dejarle a Él el resultado. A quien es consciente de Dios, Él le abre una salida y le provee de donde no lo espera. Esa confianza aligera el peso que llevamos encima."],
    ar: "رغم الاتصال الدائم يشعر كثيرون بالوحدة والتعب والقلق. والإسلام لا ينكر هذه المشاعر ولا يغني عن العلاج عند الحاجة، لكنه يقدّم صلة يومية بالله: ألا بذكر الله تطمئن القلوب، وإن مع العسر يسرًا، ودعاء موسى: رب اشرح لي صدري ويسر لي أمري. والتوكل أخذ بالأسباب وتفويض للنتيجة، ومن يتق الله يجعل له مخرجًا ويرزقه من حيث لا يحتسب." },
  { id: "a72", t: "Cómo empezar a leer el Corán", tar: "كيف تبدأ قراءة القرآن؟", si: ["coran", "primeros"], st: ["conocer", "nuevo"], au: ["general", "buscador", "nuevo", "catolico"], q: ["38:29", "54:17", "2:185"], h: [],
    es: ["Muchas personas quieren leer el Corán, pero no saben por dónde empezar. Lo primero es saber que no es un relato ordenado cronológicamente: cada capítulo (sura) habla de Dios, de los profetas, de la otra vida y de la conducta, desde ángulos distintos.", "Un buen comienzo es leer una traducción fiable, como las de QuranEnc, empezando por suras cortas: al-Fátiha, las últimas suras del Corán o la sura de María. Leer poco con atención vale más que leer mucho deprisa. El Corán dice que fue revelado para que se reflexione sobre sus versículos.", "El Corán afirma que Dios lo hizo fácil para recordarlo y lo describe como una guía para la humanidad. Si surge una duda, anótala y pregunta a alguien de confianza: el Corán se comprende mejor acompañado de su explicación (tafsir)."],
    ar: "القرآن ليس سردًا مرتبًا زمنيًا، فكل سورة تتناول الله والأنبياء والآخرة والسلوك من زوايا مختلفة. ابدأ بترجمة موثوقة كترجمات QuranEnc وبالسور القصيرة كالفاتحة وقصار السور وسورة مريم، والقليل بتدبر خير من الكثير بعجلة، فقد أُنزل ليدّبروا آياته. والله يسّره للذكر وجعله هدى للناس، فدوّن أسئلتك واسأل عنها من تثق به، واستعن بالتفسير." },
  { id: "a73", t: "Al-Fátiha: la sura de cada oración", tar: "الفاتحة: سورة كل صلاة", si: ["coran", "practicas", "primeros"], st: ["conocer", "nuevo"], au: ["general", "nuevo", "catolico", "buscador"], q: ["1:1-7"], h: [],
    es: ["Al-Fátiha, «la que abre», es la primera sura del Corán y la más recitada por los musulmanes: el musulmán la repite en cada unidad de cada oración, al menos diecisiete veces al día.", "En solo siete versículos reúne lo esencial: alabar a Dios, Señor de todos los mundos, el Compasivo, el Misericordioso; recordar que Él es el Soberano del Día del Juicio; declarar que solo a Él adoramos y solo a Él pedimos ayuda; y pedirle que nos guíe por el camino recto.", "Es una súplica que cualquier persona sincera puede entender: un ser humano que reconoce a su Creador y le pide guía. Por eso muchos nuevos musulmanes la aprenden primero, y muchos buscadores descubren en ella el corazón del islam."],
    ar: "الفاتحة أول سورة في المصحف وأكثرها تلاوة، يقرؤها المسلم في كل ركعة من كل صلاة، سبع عشرة مرة يوميًا على الأقل. تجمع في سبع آيات حمد الله رب العالمين الرحمن الرحيم، وأنه مالك يوم الدين، وإياك نعبد وإياك نستعين، وطلب الهداية إلى الصراط المستقيم. دعاء يفهمه كل صادق، ولذلك يتعلمها المسلم الجديد أولًا." },
  { id: "a74", t: "Muhammad ﷺ, el sello de los profetas", tar: "خاتم النبيين ورسالته للعالمين", si: ["profeta", "religiones"], st: ["conocer", "dudas"], au: ["general", "catolico", "protestante", "buscador"], q: ["2:136", "33:40", "21:107"], h: [],
    es: ["Los musulmanes creemos en todos los profetas que Dios envió: Noé, Abraham, Moisés, Jesús y muchos otros (la paz sea con todos ellos), sin hacer distinción entre ellos en la fe. El Corán pide a los creyentes declarar su fe en lo que fue revelado a cada uno de ellos.", "El Corán afirma que Muhammad ﷺ es el Mensajero de Dios y el sello de los profetas: después de él no vendrá ningún otro profeta. Su mensaje no es para un pueblo concreto, sino una misericordia para todos los mundos.", "Por eso el islam no se presenta como una ruptura con los profetas anteriores, sino como su culminación: el mismo mensaje de adorar solo a Dios, conservado ahora en un libro protegido y en una vida documentada con detalle."],
    ar: "نؤمن بجميع الأنبياء: نوح وإبراهيم وموسى وعيسى وغيرهم عليهم السلام، لا نفرق بين أحد منهم، والقرآن يأمرنا بالإيمان بما أُنزل إليهم. ومحمد ﷺ رسول الله وخاتم النبيين فلا نبي بعده، ورسالته رحمة للعالمين لا لقوم بعينهم. فالإسلام ليس قطيعة مع الأنبياء بل تمام رسالتهم: عبادة الله وحده، في كتاب محفوظ وسيرة موثقة." },
  { id: "a75", t: "La súplica: hablar con Dios", tar: "الدعاء: حديثك مع الله", si: ["dios", "felicidad", "sufrimiento"], st: ["contacto", "conocer", "cerca"], au: ["general", "catolico", "buscador", "indiferente", "nuevo"], q: ["2:186", "40:60", "21:87-88"], h: [],
    es: ["En el islam no hace falta un intermediario para hablar con Dios. El Corán dice que, cuando alguien pregunta por Él, Él está cerca y responde a quien le invoca. Puedes hablarle en cualquier momento, en tu propio idioma y con tus propias palabras.", "Dios mismo invita a pedirle y promete responder. La súplica (du'á) es en sí misma un acto de adoración, porque expresa que necesitamos a Dios y que confiamos en Él.", "El Corán cuenta que el profeta Jonás, en la oscuridad del vientre del pez, reconoció su error y glorificó a Dios, y Dios lo salvó de la angustia; así salva también a los creyentes. Ninguna situación es demasiado oscura para hablar con Él."],
    ar: "لا وسيط في الإسلام بين العبد وربه؛ فإذا سأل العباد عن الله فإنه قريب يجيب دعوة الداعي، في كل وقت وبأي لغة وبكلماتك أنت. والله يدعونا إلى دعائه ويعد بالإجابة، والدعاء عبادة لأنه افتقار إلى الله وثقة به. ونادى يونس في الظلمات معترفًا بخطئه مسبّحًا لله فنجّاه من الغم، وكذلك ينجي المؤمنين." }
);

RQ.FAQ.push(
  { id: "f21", es: "¿El islam está en contra de la ciencia?", ar: "هل الإسلام ضد العلم؟", aes: "No. La primera orden revelada en el Corán fue leer (iqra'), y el Corán invita a observar los cielos, la tierra y la vida como signos del Creador. El Corán no es un libro de ciencia, sino de guía, por eso evitamos forzar interpretaciones. La ciencia explica cómo funciona el mundo; la fe responde por qué existe y para qué vivimos.", aar: "لا. أول ما نزل الأمر بالقراءة، والقرآن يدعو إلى النظر في السماوات والأرض والحياة بوصفها آيات للخالق. والقرآن كتاب هداية لا كتاب علوم، فنتجنب التكلف في التفسير. العلم يشرح كيف يعمل الكون، والإيمان يجيب لماذا وُجد ولماذا نعيش.", tip: "تجنّب المبالغة في «الإعجاز العلمي» وربط الآيات بنظريات قابلة للتغير؛ ركّز على دعوة القرآن إلى التفكر.", q: ["96:1-5", "3:190", "39:9"], h: [] },
  { id: "f22", es: "¿Qué significa realmente «yihad»?", ar: "ما معنى «الجهاد» حقًا؟", aes: "Yihad significa «esfuerzo» en el camino de Dios: esforzarse contra el propio ego, por aprender y enseñar, por hacer el bien y por defender la justicia. El combate armado es una de sus formas, legítima en determinadas circunstancias y sometida a reglas estrictas: en general lo decide la autoridad legítima del Estado, no individuos ni grupos; está prohibido atacar a civiles, mujeres, niños o a quienes no combaten, y nunca sirve para obligar a nadie a hacerse musulmán. El terrorismo no es yihad: es un crimen que el islam condena. Para los detalles, consulta a sabios reconocidos.", aar: "الجهاد بذل الجهد في سبيل الله: مجاهدة النفس وطلب العلم وتعليمه وعمل الخير ونصرة العدل. والقتال صورة من صوره، مشروع في أحوال مخصوصة ومضبوط بأحكام صارمة: يرجع الأمر فيه عمومًا إلى ولي الأمر الشرعي لا إلى الأفراد والجماعات، ويحرم الاعتداء على المدنيين والنساء والأطفال وغير المقاتلين، ولا يُكره به أحد على الدخول في الإسلام. والإرهاب ليس جهادًا بل جريمة يدينها الإسلام. وتؤخذ التفاصيل عن العلماء المعتبرين.", tip: "أجب بإيجاز ووضوح، ولا تدخل في تفاصيل أحكام القتال والسياسة؛ أحِل التفصيل إلى أهل العلم.", q: ["5:32", "60:8", "2:256"], h: ["2962"] },
  { id: "f23", es: "¿Por qué el islam permite la poligamia?", ar: "لماذا يبيح الإسلام تعدد الزوجات؟", aes: "El islam permite que un hombre se case con hasta cuatro esposas, pero no lo obliga. Exige una condición estricta: la justicia entre ellas en la manutención, la vivienda y el trato; y el Corán indica casarse con una sola si se teme no ser justo. Ninguna mujer puede ser casada sin su consentimiento. En la práctica, la mayoría de los musulmanes tiene una sola esposa. Los detalles legales conviene consultarlos con un sabio.", aar: "يبيح الإسلام للرجل الزواج بأربع على الأكثر، دون إلزام، بشرط صارم هو العدل بينهن في النفقة والسكن والمعاملة، ويرشد القرآن إلى الاقتصار على واحدة عند خوف عدم العدل. ولا تُزوَّج امرأة بغير رضاها، وأكثر المسلمين في الواقع متزوجون بواحدة. وتُراجع التفاصيل مع أهل العلم.", tip: "لا تعتذر عن حكم شرعي ولا تبالغ في الدفاع؛ اذكر الشروط والحكمة باختصار، ولا تجعل المسألة محور الحوار.", q: ["4:3"], h: [] },
  { id: "f24", es: "¿Por qué la mujer hereda la mitad que el hombre?", ar: "لماذا ترث المرأة نصف الرجل؟", aes: "El Corán fija las partes de la herencia con detalle. En algunos casos, como entre hijos e hijas, la mujer recibe la mitad que el varón; pero en otros recibe lo mismo, como el padre y la madre cuando el fallecido deja un hijo varón, y en algunos casos incluso más. La razón es que el hombre está obligado a mantener a su esposa, a sus hijos y a veces a otros familiares, mientras que lo que recibe la mujer es solo suyo y no está obligada a gastarlo en nadie. Los cálculos concretos los hacen especialistas.", aar: "حدّد القرآن أنصبة الميراث تفصيلًا؛ ففي بعض الحالات كالأبناء والبنات ترث الأنثى نصف الذكر، وفي حالات أخرى تساويه كالأب والأم إذا كان للميت ابن، وفي بعضها ترث أكثر. والحكمة أن الرجل مكلف بالنفقة على زوجته وأولاده وأحيانًا غيرهم، أما ما ترثه المرأة فملك خالص لها لا تُلزم بإنفاقه. والحساب التفصيلي لأهل الاختصاص.", tip: "صحّح التعميم «المرأة ترث دائمًا النصف» بهدوء، واربط الميراث بنظام النفقة كاملًا، ولا تفتِ في حالات بعينها.", q: ["4:11"], h: [] },
  { id: "f25", es: "¿Qué pasa si un musulmán deja el islam?", ar: "ماذا يحدث إن ترك المسلم الإسلام؟", aes: "Para el musulmán, abandonar el islam es uno de los pecados más graves ante Dios. En la jurisprudencia de las escuelas sunníes, la apostasía probada es un delito grave cuya pena puede llegar a la de muerte; pero solo puede aplicarla un tribunal legítimo de un Estado islámico, tras comprobar el caso y dar a la persona la oportunidad de aclarar sus dudas y reconsiderar. Ningún particular ni grupo tiene derecho a castigar a nadie. Por eso el islam pide entrar en él con convicción y sin coacción. Es un tema técnico y delicado: para los detalles, pregunta a sabios reconocidos.", aar: "ترك الإسلام عند المسلم من أعظم الذنوب عند الله. وفي فقه المذاهب السنية تُعدّ الردة الثابتة جناية كبيرة قد تصل عقوبتها إلى القتل، لكن لا يقيمها إلا القضاء الشرعي في دولة إسلامية بعد التثبت وكشف الشبهة والاستتابة، ولا يحق لفرد ولا جماعة أن يعاقب أحدًا. ولذلك يُطلب الدخول في الإسلام عن اقتناع وبلا إكراه. والمسألة دقيقة فتُؤخذ تفاصيلها عن العلماء المعتبرين.", tip: "كن صادقًا ولا تُنكر الحكم الفقهي، ولا تستدل بآية «لا إكراه في الدين» لنفيه فهي في الدخول في الإسلام؛ أوجز وأحِل إلى أهل العلم، ولا تجعلها أول ما تتحدث فيه.", q: ["2:256"], h: [] },
  { id: "f26", es: "¿La música está prohibida en el islam?", ar: "هل الموسيقى محرمة في الإسلام؟", aes: "Es un tema que los sabios han tratado mucho. La mayoría de los sabios de las cuatro escuelas sunníes considera que los instrumentos musicales no están permitidos, con excepciones como el pandero (daf) en bodas y fiestas, mientras que el canto de la voz humana con letras buenas, sin instrumentos, se acepta. No es una condición para hacerse musulmán: el nuevo musulmán aprende y cambia poco a poco. Para los detalles, consulta a un imam de confianza.", aar: "تكلم العلماء في المسألة كثيرًا، وجمهور علماء المذاهب الأربعة على تحريم المعازف، مع استثناء الدف في الأعراس والأعياد، أما الإنشاد بالصوت البشري بكلام حسن دون معازف فمقبول. وليست شرطًا للدخول في الإسلام، والمسلم الجديد يتعلم ويتغير بالتدريج. وتُسأل التفاصيل لإمام موثوق.", tip: "لا تبدأ بالمحرّمات مع غير المسلم؛ إن سأل فأجب بأمانة وإيجاز وأحِل التفصيل إلى أهل العلم.", q: [], h: [] },
  { id: "f27", es: "¿Por qué muchos musulmanes no tienen perros en casa?", ar: "لماذا لا يقتني كثير من المسلمين الكلاب في البيوت؟", aes: "El islam manda la misericordia con todos los animales, también con los perros: maltratarlos es un pecado. Al mismo tiempo, la mayoría de los sabios enseña que no se debe tener un perro solo como mascota, aunque se permite para guardar, cazar o pastorear, y que lo que toca su saliva debe lavarse. Por eso muchos musulmanes evitan tenerlos en casa, pero nunca los desprecian ni les hacen daño. Los detalles se consultan con un imam.", aar: "يأمر الإسلام بالرحمة بكل الحيوانات ومنها الكلاب، وإيذاؤها إثم. ومع ذلك فأكثر العلماء على أنه لا يُقتنى الكلب لمجرد الزينة والتسلية، ويجوز اقتناؤه للحراسة والصيد والماشية، وما ولغ فيه يُغسل. ولذلك يتجنب كثير من المسلمين اقتناءها في البيوت دون أن يحتقروها أو يؤذوها. والتفاصيل تُسأل لأهل العلم.", tip: "ابدأ بالرحمة بالحيوان قبل الحكم الفقهي، ولا تُشعر صاحب الكلب بالازدراء.", q: [], h: [] },
  { id: "f28", es: "¿Por qué los hombres musulmanes llevan barba?", ar: "لماذا يطلق الرجال المسلمون لحاهم؟", aes: "Dejarse crecer la barba es una práctica que el Profeta Muhammad ﷺ siguió y pidió a los hombres, y la mayoría de los sabios considera que afeitarla no está permitido. Los musulmanes la llevan por amor a seguir su ejemplo, no como una costumbre cultural. Para un nuevo musulmán no es una condición para entrar en el islam: cada uno avanza poco a poco y puede consultar los detalles con un imam.", aar: "إعفاء اللحية من هدي النبي ﷺ، فعله وأمر به الرجال، وأكثر العلماء على عدم جواز حلقها. ويطلقها المسلمون محبةً في الاقتداء به لا عادةً ثقافية. وليست شرطًا للدخول في الإسلام، فكلٌّ يتدرج ويسأل إمامًا موثوقًا عن التفاصيل.", tip: "اربطها بمحبة الاقتداء، ولا تشترطها على المسلم الجديد ولا تُثقل عليه في البداية.", q: ["3:31"], h: [] },
  { id: "f29", es: "¿Por qué los musulmanes rezan en árabe?", ar: "لماذا يصلي المسلمون بالعربية؟", aes: "Porque la oración se hace con las palabras del Corán, y el Corán es el texto árabe revelado; las traducciones explican su sentido, pero no lo sustituyen. Así, un musulmán de España, de Indonesia o de Senegal reza con las mismas palabras en cualquier mezquita del mundo. Las partes necesarias son cortas y se aprenden poco a poco. Y fuera de la oración, puedes hacer súplicas personales en tu propio idioma: Dios entiende todas las lenguas.", aar: "لأن الصلاة تُؤدى بألفاظ القرآن، والقرآن هو النص العربي المنزل، والترجمة تبين معناه ولا تقوم مقامه. فيصلي المسلم من إسبانيا أو إندونيسيا أو السنغال بالكلمات نفسها في أي مسجد في العالم. والأجزاء الواجبة قصيرة تُتعلم بالتدريج، وخارج الصلاة تدعو بلغتك، فالله يعلم كل اللغات.", tip: "طمئنه أن العربية المطلوبة للصلاة يسيرة، واعرض عليه تعلّم الفاتحة خطوة خطوة.", q: ["2:186"], h: [] },
  { id: "f30", es: "¿Por qué hay distintos grupos en el islam, como sunníes y chiíes?", ar: "لماذا توجد فرق مختلفة في الإسلام كالسنة والشيعة؟", aes: "Como en otras religiones, a lo largo de la historia surgieron diferencias entre los musulmanes, algunas políticas y otras de creencia. La gran mayoría de los musulmanes del mundo son sunníes (Ahl al-Sunna wal-Yamá'a), que siguen el Corán y la Sunna auténtica tal como los entendieron los compañeros del Profeta ﷺ. Para quien empieza, lo esencial es la base: un solo Dios, el Corán y el ejemplo del Profeta. Las cuestiones sobre los grupos se estudian después, con sabios de confianza.", aar: "كما في أديان أخرى، نشأت عبر التاريخ خلافات بين المسلمين بعضها سياسي وبعضها عقدي. وجمهور المسلمين في العالم من أهل السنة والجماعة الذين يتبعون القرآن والسنة الصحيحة بفهم الصحابة. والأساس لمن يبدأ: التوحيد والقرآن والاقتداء بالنبي ﷺ، ومسائل الفرق تُدرس لاحقًا مع علماء موثوقين.", tip: "لا تدخل في جدل طائفي ولا تكفير ولا تجريح؛ أجب بإيجاز وأعد الحوار إلى الأصول المشتركة.", q: [], h: [] },
  { id: "f31", es: "¿Qué piensan los musulmanes del llamado «Estado Islámico»?", ar: "ما رأي المسلمين في ما يسمى «الدولة الإسلامية» (داعش)؟", aes: "Grupos como el llamado «Estado Islámico» (Dáesh) han sido condenados por los grandes sabios y las instituciones islámicas del mundo. Matar a inocentes y sembrar el terror contradice el Corán, que enseña que quitar una vida inocente es como matar a toda la humanidad. Además, muchísimas de sus víctimas han sido musulmanes. Juzgar el islam por ellos sería tan injusto como juzgar cualquier religión por sus peores representantes.", aar: "جماعات مثل ما يسمى «الدولة الإسلامية» (داعش) أدانها كبار العلماء والمؤسسات الإسلامية في العالم. وقتل الأبرياء وبث الرعب يناقض القرآن الذي يجعل قتل نفس بريئة كقتل الناس جميعًا، وكثير جدًا من ضحاياها مسلمون. والحكم على الإسلام بها ظلم كالحكم على أي دين بأسوأ المنتسبين إليه.", tip: "أظهر البراءة الواضحة دون انفعال، وتجنب التحليل السياسي ونظريات المؤامرة.", q: ["5:32", "5:8"], h: ["2962"] },
  { id: "f32", es: "¿Qué es la sharía?", ar: "ما الشريعة؟", aes: "Sharía significa literalmente «camino», y abarca toda la guía del islam: la oración, el ayuno, la ética, la familia, el comercio y también algunas normas penales. Según los sabios, su objetivo es proteger cinco cosas: la religión, la vida, la razón, la descendencia y los bienes. Muchas personas la reducen a castigos, pero la mayor parte de la sharía trata de cómo adorar a Dios y tratar bien a los demás.", aar: "الشريعة لغةً الطريق، وهي تشمل هدي الإسلام كله: الصلاة والصيام والأخلاق والأسرة والمعاملات وبعض الأحكام الجنائية. ومقاصدها عند العلماء حفظ الضروريات الخمس: الدين والنفس والعقل والنسل والمال. ويختزلها كثيرون في العقوبات، بينما أكثرها في عبادة الله وحسن معاملة الناس.", tip: "صحّح الصورة الإعلامية بلطف، وقدّم أمثلة يومية من الشريعة (الصدق، بر الوالدين، الوفاء بالعقود).", q: ["16:90", "21:107"], h: [] },
  { id: "f33", es: "¿Puede una mujer musulmana estudiar y trabajar?", ar: "هل يمكن للمرأة المسلمة أن تتعلم وتعمل؟", aes: "Sí. Buscar el conocimiento es un deber para todo musulmán, hombre o mujer, y en la historia del islam hubo grandes sabias, empezando por Aisha, esposa del Profeta ﷺ. La mujer también puede trabajar en lo que es lícito, y su sueldo y sus bienes le pertenecen solo a ella. El islam pide, para hombres y mujeres, un ambiente de respeto y decoro, y que el trabajo no haga descuidar las responsabilidades familiares.", aar: "نعم. طلب العلم مطلوب من كل مسلم رجلًا كان أو امرأة، وفي تاريخ الإسلام عالمات كبيرات في مقدمتهن عائشة زوج النبي ﷺ. ويجوز للمرأة العمل المباح، وراتبها ومالها ملك خالص لها. ويطلب الإسلام من الرجال والنساء بيئة احترام وحشمة، وألا يضيّع العمل المسؤوليات الأسرية.", tip: "اذكر أمثلة تاريخية موثقة، ولا تدخل في تفاصيل ضوابط الاختلاط؛ أحِلها إلى أهل العلم إن سُئلت.", q: ["33:35", "96:1-5"], h: [] },
  { id: "f34", es: "¿Creen los musulmanes que Jesús volverá?", ar: "هل يؤمن المسلمون بعودة عيسى؟", aes: "Sí. Los musulmanes creemos que Jesús (la paz sea con él) no fue crucificado ni murió en la cruz, sino que Dios lo elevó hacia Sí, y que volverá antes del fin de los tiempos para establecer la justicia. Es un punto de encuentro con los cristianos, aunque lo entendemos de otra manera: volverá como siervo y profeta de Dios, siguiendo el mensaje del islam.", aar: "نعم. نؤمن أن عيسى عليه السلام لم يُصلب ولم يُقتل، بل رفعه الله إليه، وأنه سينزل قبل قيام الساعة فيقيم العدل. وهي نقطة لقاء مع المسيحيين وإن اختلف الفهم: يعود عبدًا لله ونبيًا متبعًا لرسالة الإسلام.", tip: "ابدأ بنقطة الاتفاق (عودته) قبل الخلاف، ولا تجادل في الصلب في أول حوار.", q: ["4:157-158"], h: ["65025"] },
  { id: "f35", es: "¿En qué se diferencian la Biblia y el Corán?", ar: "ما الفرق بين الكتاب المقدس والقرآن؟", aes: "Los musulmanes creemos que Dios reveló la Torá a Moisés y el Evangelio a Jesús, y respetamos esas revelaciones en su origen. La Biblia actual es una colección de libros escritos por distintos autores a lo largo de siglos, y las distintas iglesias no aceptan exactamente los mismos libros. El Corán fue revelado a un solo profeta en unos veintitrés años, se conserva en su lengua original y se memorizó desde el principio. Por eso el Corán se presenta como confirmación de lo anterior y como criterio sobre ello.", aar: "نؤمن أن الله أنزل التوراة على موسى والإنجيل على عيسى، ونحترم هذه الكتب في أصلها. أما الكتاب المقدس اليوم فمجموعة أسفار كتبها مؤلفون متعددون عبر قرون، ولا تتفق الكنائس على الأسفار نفسها تمامًا. والقرآن أُنزل على نبي واحد في نحو ثلاث وعشرين سنة، ومحفوظ بلغته الأصلية ومحفوظ في الصدور منذ البداية، ولذلك جاء مصدقًا لما قبله ومهيمنًا عليه.", tip: "اعرض الفروق بأدب ودون سخرية أو هجوم، ولا تبدأ بها؛ اتركها لمن طلب المقارنة بنفسه.", q: ["3:3", "5:48", "15:9"], h: [] },
  { id: "f36", es: "Si todo está escrito, ¿para qué esforzarse?", ar: "إن كان كل شيء مكتوبًا فلماذا نجتهد؟", aes: "El islam enseña dos verdades a la vez: Dios lo sabe todo y nada ocurre fuera de Su voluntad, y el ser humano tiene una capacidad real de elegir y es responsable de sus actos. Que Dios sepa lo que vas a elegir no te obliga a elegirlo. Además, nadie conoce lo que está escrito para él, así que nuestro deber es esforzarnos, hacer el bien y confiar en Dios. Él no exige a nadie más de lo que puede.", aar: "يعلّم الإسلام حقيقتين معًا: الله يعلم كل شيء ولا يقع شيء خارج مشيئته، والإنسان له اختيار حقيقي وهو مسؤول عن أفعاله. وعلم الله بما ستختاره لا يجبرك عليه، ولا أحد يعلم ما كُتب له، فواجبنا السعي وعمل الخير والتوكل على الله، ولا يكلف الله نفسًا إلا وسعها.", tip: "أوجز ولا تتعمق في دقائق القدر، فهي مما يُتلقى عن أهل العلم؛ ركّز على المسؤولية والعمل.", q: ["76:2-3", "64:11", "2:286"], h: [] },
  { id: "f37", es: "¿Una buena persona que no es musulmana irá al infierno?", ar: "هل يدخل الإنسان الطيب غير المسلم النار؟", aes: "Solo Dios juzga a cada persona, y Él es perfectamente justo: no castiga a nadie a quien no le llegó el mensaje con claridad, y no se pierde ni el peso de un átomo de bien. El islam enseña que, cuando el mensaje ha llegado con claridad, la salvación eterna depende de creer en Dios y en Sus mensajeros, el último de ellos Muhammad ﷺ: las buenas obras importan mucho, pero no sustituyen a la fe. Por eso los musulmanes compartimos el mensaje con cariño. Pero no juzgamos el destino de ninguna persona concreta: eso le corresponde solo a Dios. Para profundizar, pregunta a un sabio de confianza.", aar: "الله وحده يحاسب كل إنسان، وهو العدل التام: لا يعذّب من لم تبلغه الرسالة بلاغًا واضحًا، ولا يضيع عنده مثقال ذرة من خير. ويعلّم الإسلام أن من بلغته الرسالة بلاغًا واضحًا فنجاته في الآخرة متوقفة على الإيمان بالله ورسله وخاتمهم محمد ﷺ، فالأعمال الصالحة عظيمة القدر لكنها لا تغني عن الإيمان. ولذلك نبلّغ الرسالة بمحبة، لكننا لا نحكم على مصير شخص بعينه، فذلك لله وحده. وللتوسع يُسأل عالم موثوق.", tip: "كن صادقًا في بيان أن النجاة بالإيمان، ورحيمًا في الأسلوب، ولا تحكم على أقارب السائل بأعيانهم.", q: ["17:15", "4:40", "3:85"], h: [] },
  { id: "f38", es: "¿Por qué Dios necesita que le adoremos?", ar: "لماذا يحتاج الله إلى عبادتنا؟", aes: "Dios no necesita nada de nosotros: nuestra adoración no le añade nada, y nuestra desobediencia no le quita nada. Somos nosotros quienes necesitamos adorarle, como el cuerpo necesita alimento. La adoración da sentido a la vida, paz al corazón y nos recuerda para qué fuimos creados. Es un regalo y una misericordia para nosotros, no una necesidad de Dios.", aar: "الله غني عنا؛ فلا تزيده عبادتنا شيئًا ولا تنقصه معصيتنا شيئًا. نحن المحتاجون إلى عبادته كما يحتاج الجسد إلى الغذاء، فالعبادة تمنح الحياة معنى والقلب طمأنينة وتذكّرنا بغاية خلقنا. هي نعمة ورحمة بنا لا حاجة لله.", tip: "اقلب السؤال بلطف: العبادة حاجتنا نحن، واربطها بالطمأنينة والمعنى.", q: ["51:56", "13:28"], h: [] },
  { id: "f39", es: "Si Dios lo creó todo, ¿quién creó a Dios?", ar: "إن كان الله خلق كل شيء فمن خلق الله؟", aes: "La pregunta supone que Dios es una cosa creada más, pero el Creador, por definición, no es creado: es el Primero, sin principio, y nada se le parece. Todo lo que empieza a existir necesita una causa, pero esa cadena no puede ser infinita: tiene que haber un origen que no dependa de nada. Eso es lo que los musulmanes llamamos Allah: el Único, el Eterno, que no engendró ni fue engendrado.", aar: "السؤال يفترض أن الله مخلوق كغيره، والخالق بالتعريف غير مخلوق: هو الأول بلا بداية وليس كمثله شيء. وكل ما يبدأ وجوده يحتاج إلى سبب، ولا يمكن أن تتسلسل الأسباب إلى ما لا نهاية، فلا بد من أصل لا يحتاج إلى شيء، وهو الله الأحد الصمد الذي لم يلد ولم يولد.", tip: "أجب بهدوء وبمنطق بسيط، ولا تُشعر السائل أن سؤاله ممنوع؛ ثم انتقل إلى آية «أم خُلقوا من غير شيء».", q: ["112:1-4", "42:11", "52:35"], h: [] },
  { id: "f40", es: "¿Los musulmanes celebran la Navidad?", ar: "هل يحتفل المسلمون بعيد الميلاد؟", aes: "Los musulmanes amamos y respetamos a Jesús (la paz sea con él), pero no celebramos la Navidad ni participamos en sus celebraciones, porque tenemos nuestras propias dos fiestas, Eid al-Fitr y Eid al-Adha, y porque esa fiesta expresa una creencia sobre Jesús que no compartimos: su divinidad. Eso no impide ser amables con nuestros vecinos y compañeros cristianos, respetar su libertad de celebrar y mantener una buena relación con ellos todo el año. Para más detalles, consulta a un imam de confianza.", aar: "نحب عيسى عليه السلام ونوقّره، لكننا لا نحتفل بعيد الميلاد ولا نشارك في احتفالاته، فلنا عيدانا: الفطر والأضحى، وهذا العيد يعبّر عن عقيدة في عيسى لا نؤمن بها، وهي ألوهيته. وهذا لا يمنع حسن الخلق مع جيراننا وزملائنا المسيحيين، واحترام حريتهم في الاحتفال، وحسن العلاقة بهم طوال العام. وللتفصيل يُسأل إمام موثوق.", tip: "أجب بلطف ودون تجريح. الأصل ألّا يشارك المسلم في أعيادهم الدينية ولا يهنّئ بشعائرها، وفي تفاصيل المسألة كلام لأهل العلم فأحِل السائل إليهم، وأظهر حسن الخلق معه في سائر الأيام.", q: ["3:45", "109:6", "60:8"], h: [] },
  { id: "f41", es: "¿Por qué hombres y mujeres rezan por separado en la mezquita?", ar: "لماذا يصلي الرجال والنساء منفصلين في المسجد؟", aes: "Para que todos puedan concentrarse en Dios sin distracciones durante una oración en la que uno se inclina y se postra. En tiempos del Profeta ﷺ las mujeres rezaban en la mezquita, en filas detrás de los hombres, y hoy muchas mezquitas tienen una sala o un espacio propio para ellas. No es una cuestión de valor: hombres y mujeres tienen la misma dignidad ante Dios.", aar: "ليتمكن الجميع من الخشوع دون انشغال في صلاة فيها ركوع وسجود. وفي عهد النبي ﷺ كانت النساء يصلين في المسجد في صفوف خلف الرجال، واليوم في كثير من المساجد مصلى خاص بهن. وليست المسألة مسألة قيمة؛ فللرجال والنساء الكرامة نفسها عند الله.", tip: "اربط الجواب بالخشوع والراحة لا بالتفاضل، واذكر أن النساء حاضرات في المسجد منذ العهد النبوي.", q: [], h: [] },
  { id: "f42", es: "¿Puede entrar en una mezquita alguien que no es musulmán?", ar: "هل يستطيع غير المسلم دخول المسجد؟", aes: "Sí, en general las personas no musulmanas son bienvenidas en las mezquitas, y muchas organizan jornadas de puertas abiertas. Basta con vestir con decoro, quitarse los zapatos antes de entrar en la sala de oración y respetar a quienes rezan; en algunas mezquitas se pide a las mujeres cubrirse el cabello. La excepción es el recinto sagrado de La Meca, reservado a los musulmanes. Visitar una mezquita es una excelente forma de conocer el islam de cerca.", aar: "نعم، غير المسلمين مرحَّب بهم عمومًا في المساجد، وكثير منها ينظم أيام زيارة مفتوحة. يكفي اللباس المحتشم وخلع الحذاء قبل دخول المصلى واحترام المصلين، وقد تطلب بعض المساجد من النساء تغطية الشعر. ويُستثنى الحرم المكي فهو خاص بالمسلمين. وزيارة المسجد طريقة ممتازة للتعرف على الإسلام عن قرب.", tip: "ادعه إلى زيارة مسجدك برفقتك، ونسّق مسبقًا مع إدارة المسجد.", q: [], h: [] },
  { id: "f43", es: "¿Qué significa «halal»?", ar: "ما معنى «حلال»؟", aes: "Halal significa «lícito», lo que Dios permite. Se aplica a la comida, pero también al dinero, al trabajo y a la conducta. En la comida, casi todo es halal salvo unas pocas excepciones, como el cerdo, el alcohol, la sangre, la carne de animales muertos por sí mismos y la de los no sacrificados según las normas islámicas. La idea es sencilla: lo bueno está permitido y lo dañino se prohíbe.", aar: "الحلال هو المباح الذي أذن الله فيه، ويشمل الطعام والمال والعمل والسلوك. وفي الطعام الأصل الحِل إلا استثناءات قليلة كالخنزير والخمر والدم والميتة وما لم يُذكَّ ذكاة شرعية. والفكرة بسيطة: الطيبات حلال والخبائث حرام.", tip: "ابدأ بأن الأصل في الطعام الإباحة، ثم اذكر المحرمات القليلة دون تشدد.", q: ["2:172-173", "5:90"], h: [] },
  { id: "f44", es: "¿Por qué los musulmanes se lavan antes de rezar?", ar: "لماذا يتوضأ المسلمون قبل الصلاة؟", aes: "Antes de la oración, el musulmán hace la ablución (wudú): se lava con agua las manos, la boca, la nariz, la cara y los brazos, se pasa las manos mojadas por la cabeza y las orejas, y se lava los pies. Es limpieza física y también espiritual: uno se prepara para presentarse ante Dios con el cuerpo y el corazón limpios. Solo lleva unos minutos.", aar: "يتوضأ المسلم قبل الصلاة: يغسل كفيه ويتمضمض ويستنشق ويغسل وجهه ويديه إلى المرفقين ويمسح رأسه وأذنيه ويغسل رجليه. وهي طهارة للبدن والروح؛ يستعد بها للوقوف بين يدي الله نظيف الجسد والقلب، ولا تستغرق إلا دقائق.", tip: "يمكنك أن تريه الوضوء عمليًا إن أبدى اهتمامًا؛ التجربة أوضح من الشرح.", q: ["5:6"], h: [] },
  { id: "f45", es: "¿Los musulmanes adoran la Kaaba o una piedra?", ar: "هل يعبد المسلمون الكعبة أو حجرًا؟", aes: "No. Los musulmanes no adoran la Kaaba ni ninguna piedra: adoran solo a Dios. La Kaaba es una casa dedicada a la adoración del Dios único, levantada por Abraham y su hijo Ismael, y sirve como dirección común de la oración, que une a los creyentes de todo el mundo. Si los peregrinos besan la Piedra Negra, es solo para seguir el ejemplo del Profeta ﷺ; como dijo el califa Omar, es una piedra que no beneficia ni perjudica.", aar: "لا. المسلمون لا يعبدون الكعبة ولا أي حجر، بل يعبدون الله وحده. والكعبة بيت لعبادة الله الواحد رفع قواعده إبراهيم وإسماعيل، وهي قبلة جامعة توحّد المسلمين في العالم. وتقبيل الحجر الأسود اتباع للنبي ﷺ فحسب، كما قال عمر رضي الله عنه: إنه حجر لا يضر ولا ينفع.", tip: "اشرح معنى القبلة بوصفها وحدةً واتجاهًا لا معبودًا، وابدأ بالتوحيد.", q: ["2:127", "112:1-4"], h: [] },
  { id: "f46", es: "¿Qué es la peregrinación (Hajj)?", ar: "ما الحج؟", aes: "Es la peregrinación a La Meca, el quinto pilar del islam, obligatoria una vez en la vida para quien tenga salud y medios. Cada año, personas de todos los países acuden en los mismos días; los hombres visten dos telas blancas sencillas, iguales para todos, y siguen los pasos de Abraham y de su familia. Es una gran lección de igualdad, sencillez y entrega a Dios.", aar: "الحج قصد مكة لأداء المناسك، وهو الركن الخامس، ويجب مرة في العمر على المستطيع صحةً ومالًا. يجتمع فيه الناس من كل البلاد في أيام واحدة، ويلبس الرجال إزارًا ورداءً أبيضين متماثلين، ويتتبعون آثار إبراهيم وأهله. إنه درس عظيم في المساواة والبساطة والاستسلام لله.", tip: "اربطه بإبراهيم عليه السلام، فهو نقطة مشتركة مع اليهود والنصارى.", q: ["2:127", "22:78", "49:13"], h: ["66512"] },
  { id: "f47", es: "¿Qué es el azaque (zakat)?", ar: "ما الزكاة؟", aes: "El azaque es el tercer pilar del islam: una contribución anual obligatoria, en general del 2,5 % del ahorro que supera un mínimo y se ha conservado durante un año lunar, destinada a los pobres y a las demás categorías de beneficiarios que señala el Corán. No es un favor, sino un derecho de los necesitados sobre la riqueza, y purifica el dinero y el corazón del egoísmo. Además existe la caridad voluntaria, que se puede dar en cualquier momento.", aar: "الزكاة الركن الثالث: حق سنوي واجب، غالبًا ربع العشر من المال الذي بلغ النصاب وحال عليه الحول الهجري، يُصرف للفقراء وسائر المستحقين. وهي حق لهم لا منّة، وتطهّر المال والقلب من الشح. وهناك أيضًا الصدقة التطوعية في كل وقت.", tip: "قدّمها بوصفها نظام تكافل اجتماعي، ولا تدخل في تفاصيل الأنصبة إلا لمن أسلم.", q: ["2:261", "76:8-9"], h: ["66512"] },
  { id: "f48", es: "¿Puede un musulmán casarse con alguien que no es musulmán?", ar: "هل يجوز للمسلم أن يتزوج من غير المسلمة؟", aes: "Según el Corán y la enseñanza unánime de los sabios, la mujer musulmana solo puede casarse con un hombre musulmán. El hombre musulmán puede casarse con una musulmana o con una cristiana o judía casta, aunque muchos sabios lo desaconsejan, sobre todo hoy y fuera de los países musulmanes; pero no con una mujer de otra religión ni sin religión. Detrás de estas normas está la protección de la fe en la familia. Es una decisión importante con muchos detalles (condiciones del contrato, derechos, educación de los hijos), así que lo mejor es consultar con un imam o un sabio de confianza.", aar: "بنص القرآن وإجماع العلماء لا تتزوج المسلمة إلا مسلمًا. ويجوز للمسلم أن يتزوج مسلمة أو كتابية عفيفة (نصرانية أو يهودية)، وإن كره ذلك كثير من العلماء ولا سيما في هذا الزمان وفي غير بلاد المسلمين، ولا يجوز له نكاح من سواهما من المشركات والملحدات. والحكمة حفظ الدين في الأسرة. وهو قرار مهم له تفاصيل كثيرة (شروط العقد والحقوق وتربية الأولاد)، فالأولى استشارة إمام أو عالم موثوق.", tip: "بيّن المتفق عليه باختصار (لا تتزوج المسلمة غير مسلم)، ولا تُفتِ في حالة شخصية؛ أحِل السائل إلى عالم أو مركز إسلامي موثوق.", q: ["5:5", "2:221"], h: [] },
  { id: "f49", es: "¿Por qué la sharía tiene castigos tan duros?", ar: "لماذا في الشريعة عقوبات قاسية؟", aes: "La sharía contiene algunas penas fijas para delitos graves, como el robo. Pero su aplicación corresponde solo a un tribunal legítimo de un Estado islámico, nunca a individuos, y exige condiciones muy estrictas: pruebas plenas, ausencia de duda y que la persona sea plenamente responsable. Los sabios establecieron el principio de que la duda impide aplicar la pena. Su objetivo es proteger a la sociedad y disuadir del delito, y para quien la recibe es también una expiación. Para profundizar, conviene consultar a sabios especialistas.", aar: "في الشريعة عقوبات مقدّرة لجرائم كبيرة كالسرقة، لكن لا يقيمها إلا القضاء الشرعي في دولة إسلامية لا الأفراد، وبشروط صارمة: ثبوت تام وانتفاء الشبهة وكمال أهلية الجاني، وقرر العلماء أن الحدود تُدرأ بالشبهات. ومقصدها حماية المجتمع والزجر عن الجريمة، وهي كفارة لمن أقيمت عليه، والتفصيل لأهل العلم المتخصصين.", tip: "لا تُنكر الحدود ولا تعتذر عنها، ولا تبدأ بها؛ بيّن شروطها ومقاصدها وأن تطبيقها للقضاء الشرعي وحده.", q: [], h: [] },
  { id: "f50", es: "¿El islam se extendió por la espada?", ar: "هل انتشر الإسلام بالسيف؟", aes: "La historia muestra otra cosa. Hubo guerras y conquistas, como en todos los imperios, pero el islam prohíbe obligar a nadie a creer, y en muchas tierras gobernadas por musulmanes los cristianos y los judíos conservaron su fe durante siglos. Además, el país con más musulmanes del mundo, Indonesia, y amplias zonas de Asia y de África conocieron el islam sobre todo por comerciantes y predicadores, no por ejércitos.", aar: "التاريخ يقول غير ذلك؛ فقد وقعت حروب وفتوح كما في كل الدول، لكن الإسلام يحرّم إكراه أحد على الإيمان، وبقي النصارى واليهود على دينهم قرونًا في بلاد حكمها المسلمون. وأكبر بلد مسلم في العالم، إندونيسيا، ومناطق واسعة من آسيا وإفريقيا عرفت الإسلام غالبًا عن طريق التجار والدعاة لا الجيوش.", tip: "استشهد بالوقائع التاريخية بهدوء، ولا تنكر وقوع الحروب؛ فرّق بين الفتح وإكراه الأفراد على الدين.", q: ["2:256", "60:8"], h: [] },
  { id: "f51", es: "¿Qué piensan los musulmanes de los judíos y los cristianos?", ar: "ما موقف المسلمين من اليهود والنصارى؟", aes: "El Corán los llama «Gente del Libro», porque recibieron revelaciones anteriores, y pide dialogar con ellos de la mejor manera. Los musulmanes creemos en Moisés y en Jesús y en las escrituras que trajeron en su origen. Tenemos diferencias de creencia importantes, sobre todo acerca de Dios y de Jesús, pero el Corán invita a una palabra común: adorar solo a Dios. Y manda ser justos con todos y bondadosos con quienes viven en paz con nosotros.", aar: "يسميهم القرآن «أهل الكتاب» لأنهم أوتوا كتبًا من قبل، ويأمر بمجادلتهم بالتي هي أحسن. ونؤمن بموسى وعيسى وبما أُنزل عليهما في أصله. وبيننا خلافات عقدية مهمة خاصة في شأن الله وعيسى، لكن القرآن يدعو إلى كلمة سواء: ألا نعبد إلا الله، ويأمر بالعدل مع الجميع والبر بالمسالمين.", tip: "ابدأ بالمشترك والاحترام، وبيّن الخلاف العقدي بوضوح دون تجريح.", q: ["29:46", "3:64", "5:8"], h: [] },
  { id: "f52", es: "¿Qué son la Sunna y el hadiz?", ar: "ما السنة وما الحديث؟", aes: "La Sunna es el ejemplo del Profeta Muhammad ﷺ: sus palabras, sus actos y lo que aprobó. Se ha transmitido en los hadices, que los sabios estudiaron con gran rigor, examinando quién lo transmitió de quién para distinguir lo auténtico de lo débil. El Corán y la Sunna van juntos: el Corán da los principios y la Sunna muestra cómo vivirlos, por ejemplo, cómo se reza.", aar: "السنة هدي النبي ﷺ: أقواله وأفعاله وتقريراته، ونُقلت في الأحاديث التي درسها العلماء بدقة بالغة بفحص الأسانيد للتمييز بين الصحيح والضعيف. والقرآن والسنة متلازمان: القرآن يقرر الأصول والسنة تبين كيفية العمل بها، كصفة الصلاة.", tip: "انصح باعتماد مصادر موثوقة مثل HadeethEnc، وحذّر من الأحاديث المنتشرة بلا تخريج.", q: ["3:31", "33:21"], h: [] },
  { id: "f53", es: "¿El islam es la religión de los árabes?", ar: "هل الإسلام دين العرب؟", aes: "No. El islam es un mensaje para toda la humanidad. Hoy la mayoría de los musulmanes no son árabes: los países con más musulmanes están en Asia, como Indonesia, Pakistán, la India o Bangladés. El Corán enseña que Dios nos hizo pueblos y tribus para que nos conozcamos, y que el más noble ante Él es el más piadoso, no el de una raza o una lengua.", aar: "لا. الإسلام رسالة للناس كافة، وأكثر المسلمين اليوم ليسوا عربًا، فأكبر البلدان المسلمة في آسيا كإندونيسيا وباكستان والهند وبنغلاديش. والقرآن يعلّم أن الله جعلنا شعوبًا وقبائل لنتعارف، وأن أكرمنا عنده أتقانا لا صاحب عرق أو لسان.", tip: "مفيد مع من يربط الإسلام بثقافة معينة؛ أكّد أنه يستطيع أن يبقى إسبانيًا أو لاتينيًا بثقافته المباحة.", q: ["49:13", "21:107"], h: ["4555"] },
  { id: "f54", es: "¿Creen los musulmanes en el pecado original?", ar: "هل يؤمن المسلمون بالخطيئة الأصلية؟", aes: "No. El islam enseña que Adán y Eva se equivocaron, se arrepintieron y Dios los perdonó. Cada persona nace pura, con una inclinación natural hacia Dios, y nadie carga con el pecado de otro: cada uno responde solo de sus propios actos. Por eso no hace falta que otro pague por nosotros; basta con volver a Dios con sinceridad, y Él perdona.", aar: "لا. يعلّم الإسلام أن آدم وحواء أخطآ فتابا فتاب الله عليهما. وكل إنسان يولد على الفطرة، ولا تزر وازرة وزر أخرى، فكلٌّ مسؤول عن عمله وحده. ولذلك لا يحتاج أحد إلى من يفتديه؛ يكفي أن يرجع إلى الله صادقًا، والله يغفر.", tip: "اعرضها بلطف بوصفها رحمة وعدلًا، ولا تهاجم عقيدة الفداء مباشرة.", q: ["53:38-39", "30:30", "39:53"], h: [] },
  { id: "f55", es: "¿Qué pasa después de la muerte según el islam?", ar: "ماذا يحدث بعد الموت في الإسلام؟", aes: "El islam enseña que la muerte no es el final, sino el paso a otra etapa. El alma pasa a una etapa intermedia (barzaj) en espera del Día de la Resurrección, cuando Dios devolverá la vida a todos y juzgará a cada uno con justicia perfecta: nada del bien ni del mal, ni siquiera el peso de un átomo, se perderá. Después viene la vida eterna en el Paraíso o en el Infierno, según la fe y las obras, y con la misericordia de Dios.", aar: "الموت ليس النهاية بل انتقال إلى مرحلة أخرى؛ تنتقل الروح إلى البرزخ في انتظار يوم القيامة حين يبعث الله الجميع ويحاسب كل إنسان بعدل تام، فلا يضيع مثقال ذرة من خير أو شر. ثم الحياة الأبدية في الجنة أو النار بحسب الإيمان والعمل وبرحمة الله.", tip: "إن كان السائل فقد عزيزًا فابدأ بالمواساة، ثم قدّم الجواب برفق.", q: ["3:185", "36:78-79", "99:7-8"], h: [] },
  { id: "f56", es: "¿Los musulmanes adoran a Muhammad?", ar: "هل يعبد المسلمون محمدًا ﷺ؟", aes: "No. Los musulmanes amamos y respetamos profundamente al Profeta Muhammad ﷺ, pero no lo adoramos ni le rezamos: fue un ser humano, siervo y mensajero de Dios. El Corán le ordena decir que es un ser humano como los demás, a quien se le revela que Dios es uno solo. Por eso el término «mahometanos» no es adecuado: adoramos a Dios, no a Muhammad.", aar: "لا. نحب النبي محمدًا ﷺ ونوقّره، لكننا لا نعبده ولا ندعوه؛ فهو بشر وعبد لله ورسوله. وقد أمره القرآن أن يقول إنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله واحد. ولذلك لا يصح وصف المسلمين بـ«المحمديين»؛ فنحن نعبد الله لا محمدًا.", tip: "صحّح المصطلح بلطف، واذكر أن تعظيم النبي ﷺ يكون باتباعه لا بعبادته.", q: ["18:110", "33:40"], h: [] },
  { id: "f57", es: "¿Por qué los musulmanes dicen «in sha Allah»?", ar: "لماذا يقول المسلمون «إن شاء الله»؟", aes: "«In sha Allah» significa «si Dios quiere». El musulmán lo dice cuando habla de lo que hará en el futuro, porque reconoce que todo depende de la voluntad de Dios, como enseña el Corán. No es una forma de evitar compromisos: el islam manda cumplir la palabra dada. Es una expresión de humildad y de confianza en Dios.", aar: "«إن شاء الله» معناها: إذا أراد الله. يقولها المسلم حين يتحدث عما سيفعله مستقبلًا، اعترافًا بأن كل شيء بمشيئة الله كما علّم القرآن. وليست تهربًا من الالتزام، فالإسلام يأمر بالوفاء بالوعد، بل هي تعبير عن التواضع والتوكل.", tip: "كن قدوة: إذا قلت «إن شاء الله» فأوفِ بوعدك، فهذا يصحح الصورة الشائعة.", q: ["18:23-24"], h: [] },
  { id: "f58", es: "¿Pueden los musulmanes tener amigos que no son musulmanes?", ar: "هل يمكن للمسلمين مصادقة غير المسلمين؟", aes: "Sí. El Corán enseña que Dios no prohíbe ser bondadosos y justos con quienes no nos combaten por nuestra religión. Un musulmán puede tener compañeros, vecinos y amigos de otras creencias, ayudarlos, visitarlos cuando están enfermos y compartir la vida cotidiana con ellos. El Profeta ﷺ enseñó que los mejores son los de mejor carácter.", aar: "نعم. يعلّم القرآن أن الله لا ينهانا عن البر والقسط مع من لم يقاتلونا في الدين. فللمسلم زملاء وجيران وأصدقاء من أديان أخرى، يعينهم ويعودهم إذا مرضوا ويشاركهم الحياة اليومية، وخيارنا أحاسننا أخلاقًا.", tip: "صداقتك نفسها دعوة؛ أظهر الوفاء وحسن المعاملة قبل أي حديث ديني. والمقصود حسن الصحبة والبر، لا الموالاة على الدين أو إقرار ما يخالف التوحيد.", q: ["60:8", "5:8"], h: ["5803"] },
  { id: "f59", es: "¿Se puede ser musulmán y vivir en España o en América Latina?", ar: "هل يمكن أن أكون مسلمًا وأعيش في إسبانيا أو أمريكا اللاتينية؟", aes: "Sí. Muchos musulmanes viven en España y en América Latina como ciudadanos que trabajan, estudian y participan en la sociedad. El islam manda cumplir los compromisos y devolver lo confiado, ser honrado, tratar bien a los vecinos y ser justo con todos. Un buen musulmán intenta ser también un buen ciudadano y un buen vecino.", aar: "نعم. يعيش مسلمون كثيرون في إسبانيا وأمريكا اللاتينية مواطنين يعملون ويدرسون ويشاركون في المجتمع. والإسلام يأمر بالوفاء بالعهود وأداء الأمانات والصدق والإحسان إلى الجيران والعدل مع الجميع، فالمسلم الصالح يسعى أن يكون مواطنًا صالحًا وجارًا طيبًا.", tip: "طمئنه، وعرّفه على مسجد أو مركز إسلامي قريب في مدينته.", q: ["4:58", "16:90"], h: [] },
  { id: "f60", es: "Si me hago musulmán, ¿tengo que dejar a mi familia?", ar: "إن أسلمت فهل عليّ أن أترك أهلي؟", aes: "No. El islam ordena tratar bien a los padres y a la familia aunque no sean musulmanes: visitarlos, ayudarlos y hablarles con respeto. Solo no se obedece a nadie en algo que vaya contra Dios. De hecho, muchas familias se acercan al islam al ver cómo ha mejorado el carácter de su hijo o de su hija. Paso a paso, con paciencia y cariño.", aar: "لا. يأمر الإسلام بالإحسان إلى الوالدين والأهل وإن لم يكونوا مسلمين: زيارتهم وإعانتهم ومخاطبتهم باحترام، ولا طاعة لأحد في معصية الله. وكثير من الأسر تقترب من الإسلام حين ترى تحسّن أخلاق ابنها أو ابنتها. خطوة خطوة بالصبر والمحبة.", tip: "أزل هذا الخوف مبكرًا، وانصحه بالتدرج في إخبار أهله وبإظهار البر قبل الجدال.", q: ["31:15", "17:23"], h: ["5866"] }
);
